def _deviations_maket_task_id_col(frame: pd.DataFrame) -> str | None:
    if frame is None or getattr(frame, "empty", True):
        return None
    lower_map = {str(c).strip().lower(): c for c in frame.columns}
    for key in (
        "unique id", "unique_id", "task id seq", "task id", "ид", "id",
        "уникальный_идентификатор", "external task id",
    ):
        if key in lower_map:
            return lower_map[key]
    return None


def _deviations_maket_prepare_df(table_reason_df: pd.DataFrame) -> pd.DataFrame:
    """MSP level 5, filled reason, finish deviation < 0; sort by deviation descending (max at top)."""
    if table_reason_df is None or getattr(table_reason_df, "empty", True):
        return table_reason_df.iloc[0:0].copy() if table_reason_df is not None else pd.DataFrame()
    work_m = table_reason_df.copy()
    _reason_col_m = _gantt_resolve_reason_column(work_m)
    if _reason_col_m and _reason_col_m != "reason of deviation":
        work_m = work_m.rename(columns={_reason_col_m: "reason of deviation"})
    if "_dt_lvl3_key" not in work_m.columns or "_dt_lvl2_key" not in work_m.columns:
        _lc_m = _dev_tasks_resolve_level_column(work_m)
        _tc_m = (
            "task name" if "task name" in work_m.columns
            else find_column(work_m, ["Задача", "task", "Task Name", "Название"])
        )
        if _lc_m and _tc_m:
            work_m = _dev_tasks_build_ancestor_keys(work_m, _lc_m, _tc_m)
    try:
        ensure_date_columns(work_m)
    except Exception:
        pass
    if "plan end" in work_m.columns:
        work_m["plan end"] = _deviations_coerce_datetime(work_m["plan end"])
    if "base end" in work_m.columns:
        work_m["base end"] = _deviations_coerce_datetime(work_m["base end"])
    work_m["_end_diff"] = np.nan
    if "plan end" in work_m.columns and "base end" in work_m.columns:
        _m = work_m["plan end"].notna() & work_m["base end"].notna()
        work_m.loc[_m, "_end_diff"] = (
            work_m.loc[_m, "base end"] - work_m.loc[_m, "plan end"]
        ).dt.total_seconds() / 86400.0
    mask_r = pd.Series(True, index=work_m.index)
    if "reason of deviation" in work_m.columns:
        mask_r = (
            work_m["reason of deviation"].notna()
            & (work_m["reason of deviation"].astype(str).str.strip() != "")
        )
    mask_l = pd.Series(True, index=work_m.index)
    # Макет (ТЗ): «уровень 5» — колонка «Уровень» (level), не outline (level structure).
    # В MSP-выгрузках (напр. Есипово) Уровень=5 при Уровень_структуры=3.
    if "level" in work_m.columns and pd.to_numeric(work_m["level"], errors="coerce").notna().any():
        mask_l = pd.to_numeric(work_m["level"], errors="coerce") == 5
    else:
        _lc_maket = _dev_tasks_resolve_level_column(work_m)
        if _lc_maket and _lc_maket in work_m.columns:
            mask_l = pd.to_numeric(work_m[_lc_maket], errors="coerce") == 5
    mask_neg = work_m["_end_diff"].notna() & (work_m["_end_diff"] < 0)
    maket_df = work_m[mask_r & mask_l & mask_neg].copy()
    _dd_key_cols = [
        c for c in ["project name", "task name", "plan end", "base end", "reason of deviation"]
        if c in maket_df.columns
    ]
    if _dd_key_cols and not maket_df.empty:
        _dd_tmp = maket_df.copy()
        for _ddc in _dd_key_cols:
            _dd_tmp[_ddc] = _dd_tmp[_ddc].astype(str).str.strip()
        maket_df = maket_df[~_dd_tmp.duplicated(subset=_dd_key_cols, keep="first")].copy()
    if not maket_df.empty:
        maket_df = maket_df.sort_values("_end_diff", ascending=False).reset_index(drop=True)
    return maket_df


def _deviations_maket_scope_df(table_reason_df: pd.DataFrame) -> pd.DataFrame:
    """Макет (ур. 5, причина, окончание < 0) + колонки для агрегации диаграмм."""
    out = _deviations_maket_prepare_df(table_reason_df)
    if out.empty:
        return out
    out = out.copy()
    out["_maket_cnt"] = 1
    if "_end_diff" in out.columns:
        out["deviation in days"] = pd.to_numeric(out["_end_diff"], errors="coerce").abs()
    return out


def _deviations_maket_grouped_rename(grouped_data: pd.DataFrame) -> pd.DataFrame:
    """Переименование колонок после groupby по макет-данным."""
    g = grouped_data.copy()
    cnt_src = "_maket_cnt" if "_maket_cnt" in g.columns else "deviation"
    if "deviation in days" in g.columns:
        g = g.rename(
            columns={
                cnt_src: "Количество задач",
                "deviation in days": "Всего дней отклонений",
            }
        )
        _cnt = g["Количество задач"].replace(0, np.nan)
        g["Среднее дней отклонений"] = (
            g["Всего дней отклонений"] / _cnt
        ).round(0).fillna(0)
    else:
        g = g.rename(columns={cnt_src: "Количество задач"})
        g["Всего дней отклонений"] = 0
        g["Среднее дней отклонений"] = 0
    return g


def _deviations_period_labels_nonzero(
    period_labels: list,
    frame: pd.DataFrame,
    *,
    period_col: str = "period",
    value_col: str = "Количество задач",
) -> list:
    """Ось X: только периоды с ненулевым итогом (без пустого хвоста до первой точки)."""
    if not period_labels or frame is None or getattr(frame, "empty", True):
        return list(period_labels or [])
    if period_col not in frame.columns or value_col not in frame.columns:
        return list(period_labels)
    try:
        totals = (
            frame.groupby(period_col, observed=False)[value_col]
            .sum()
            .astype(float)
        )
    except Exception:
        return list(period_labels)
    nz = {str(k) for k, v in totals.items() if float(v) > 0}
    trimmed = [p for p in period_labels if str(p) in nz]
    return trimmed if trimmed else list(period_labels)


def _deviations_coerce_datetime(series: pd.Series) -> pd.Series:
    """ISO YYYY-MM-DD из БД — без dayfirst; DD.MM.YY из MSP CSV — с dayfirst."""
    if series is None or getattr(series, "empty", True):
        return series
    if pd.api.types.is_datetime64_any_dtype(series.dtype):
        return pd.to_datetime(series, errors="coerce")
    raw = series.copy()
    as_str = raw.astype(str).str.strip()
    invalid = as_str.str.lower().isin(["", "nan", "none", "nat", "нд", "nd"])
    iso = as_str.str.match(r"^\d{4}-\d{2}-\d{2}", na=False)
    out = pd.Series(pd.NaT, index=raw.index, dtype="datetime64[ns]")
    if iso.any():
        out.loc[iso] = pd.to_datetime(raw.loc[iso], errors="coerce")
    other = ~invalid & ~iso
    if other.any():
        out.loc[other] = pd.to_datetime(raw.loc[other], errors="coerce", dayfirst=True)
    return out


def _deviations_exclude_future_plan_rows(
    df: pd.DataFrame,
    *,
    date_col: str = "plan end",
    period_type_en: str = "Month",
) -> pd.DataFrame:
    """Не считать отклонения с датой в будущем календарном периоде."""
    if df is None or getattr(df, "empty", True):
        return df
    if date_col not in df.columns:
        return df
    dt = _deviations_coerce_datetime(df[date_col])
    mask = dt.notna()
    if not mask.any():
        return df
    today = pd.Timestamp(date.today())
    if period_type_en == "Day":
        keep = dt.loc[mask].dt.normalize() <= today.normalize()
    elif period_type_en == "Quarter":
        cutoff = today.to_period("Q")
        keep = dt.loc[mask].dt.to_period("Q") <= cutoff
    elif period_type_en == "Year":
        cutoff = today.to_period("Y")
        keep = dt.loc[mask].dt.to_period("Y") <= cutoff
    else:
        cutoff = today.to_period("M")
        keep = dt.loc[mask].dt.to_period("M") <= cutoff
    out_mask = pd.Series(False, index=df.index)
    out_mask.loc[mask] = keep
    return df[out_mask].copy()


def _deviations_stacked_bar_add_totals(
    fig,
    frame: pd.DataFrame,
    *,
    period_col: str,
    value_col: str,
    min_segments: int = 1,
) -> None:
    if frame is None or frame.empty or period_col not in frame.columns or value_col not in frame.columns:
        return
    tot = (
        frame.groupby(period_col, observed=False)[value_col]
        .sum()
        .reset_index()
    )
    for _, row in tot.iterrows():
        x_pos = row[period_col]
        sub = frame[frame[period_col].astype(str) == str(x_pos)]
        nz = pd.to_numeric(sub[value_col], errors="coerce").fillna(0)
        if (nz != 0).sum() < min_segments:
            continue
        v = row[value_col]
        if pd.isna(v) or float(v) == 0:
            continue
        txt = str(int(round(float(v), 0)))
        fv = float(v)
        fig.add_annotation(
            x=x_pos,
            y=fv,
            text=f"<b>{txt}</b>",
            showarrow=False,
            xref="x",
            yref="y",
            xanchor="center",
            yanchor="bottom",
            yshift=10,
            font=dict(color="#f5f5f5", size=14),
        )


def _deviations_plotly_project_chart_title(fig, project_name: str) -> None:
    name = str(project_name or "").strip()
    if not name:
        return
    try:
        fig.update_layout(
            title=dict(text=name, x=0.5, xanchor="center", font=dict(size=18, color="#e8eef5")),
            margin=dict(t=72),
        )
        _pn_prefixes = ("project name=", "Проект=", "project=")
        fig.for_each_annotation(
            lambda a: a.update(text=name)
            if a.text
            and any(str(a.text).startswith(p) for p in _pn_prefixes)
            else None
        )
    except Exception:
        pass


def _dev_days_diff(a, b):
    """Разница (a − b) в днях; NaN если нет дат."""
    if a is None or b is None:
        return np.nan
    try:
        if isinstance(a, float) and pd.isna(a):
            return np.nan
        if isinstance(b, float) and pd.isna(b):
            return np.nan
    except Exception:
        pass
    try:
        ta = pd.Timestamp(a)
        tb = pd.Timestamp(b)
        if pd.isna(ta) or pd.isna(tb):
            return np.nan
        return (ta - tb).total_seconds() / 86400.0
    except Exception:
        return np.nan


def _fmt_date_cell(v):
    if v is None or (isinstance(v, float) and pd.isna(v)):
        return ""
    try:
        t = pd.Timestamp(v)
        if pd.isna(t):
            return ""
        return t.strftime("%d.%m.%Y")
    except Exception:
        return str(v).strip() if v is not None else ""


def _fmt_int_days(v):
    if v is None or (isinstance(v, float) and pd.isna(v)):
        return ""
    try:
        return str(int(round(float(v), 0)))
    except (TypeError, ValueError):
        return ""


def _deviations_full_table_build(table_reason_df, notes_col=None):
    """
    Строки полной таблицы «Причины отклонений»: словари для CSV/Excel и ячейки для HTML.
    Возвращает (headers, rows_out, cells_rows) или ([], [], []) если данных нет.
    """
    if table_reason_df is None or getattr(table_reason_df, "empty", True):
        return [], [], []
    d = table_reason_df.copy()
    for c in ("plan start", "plan end", "base start", "base end"):
        if c in d.columns:
            d[c] = pd.to_datetime(d[c], errors="coerce", dayfirst=True)
    reason_col = (
        "reason of deviation"
        if "reason of deviation" in d.columns
        else _find_column_by_keywords(d, ("причина отклон", "reason of deviation", "reason"))
    )
    notes_col_eff = (
        notes_col
        if notes_col and notes_col in d.columns
        else _find_column_by_keywords(d, ("заметк", "note", "comment", "remark", "notes"))
    )

    headers = ["Проект", "Задача"]
    if "block" in d.columns:
        headers.append("Функциональный блок")
    headers.extend(
        [
            "Начало",
            "Базовое начало",
            "Отклонение начала",
            "Окончание",
            "Базовое окончание",
            "Отклонение окончания",
            "Базовая длительность",
            "Длительность",
            "Причина отклонений",
            "Заметки",
        ]
    )
    if "snapshot_date" in d.columns:
        headers.append("Дата снимка")

    rows_out = []
    cells_rows = []
    for _, row in d.iterrows():
        ps = row.get("plan start")
        pe = row.get("plan end")
        bs = row.get("base start")
        be = row.get("base end")
        start_dev = _dev_days_diff(ps, bs)
        end_dev = _dev_days_diff(be, pe)
        dur_b = _dev_days_diff(pe, ps)
        dur_f = _dev_days_diff(be, bs)

        pr = _clean_display_str(row.get("project name"))
        tn = _clean_display_str(row.get("task name"))
        cells = [
            ("", pr),
            ("", tn),
        ]
        if "block" in d.columns:
            cells.append(("", _clean_display_str(row.get("block"))))
        cells.extend(
            [
                ("dev-bg-turq", _fmt_date_cell(bs)),
                ("dev-bg-turq", _fmt_date_cell(ps)),
                (
                    "dev-bg-lblue",
                    _fmt_int_days(start_dev),
                    "start_dev",
                    start_dev,
                ),
                ("dev-bg-blue", _fmt_date_cell(be)),
                ("dev-bg-blue", _fmt_date_cell(pe)),
                (
                    "dev-bg-lblue",
                    _fmt_int_days(end_dev),
                    "end_dev",
                    end_dev,
                ),
                ("dev-bg-dblue", _fmt_int_days(dur_b)),
                ("dev-bg-dblue", _fmt_int_days(dur_f)),
                (
                    "dev-reason-cell",
                    _clean_display_str(row.get(reason_col))
                    if reason_col and reason_col in d.columns
                    else "",
                    "reason_label",
                    (
                        _deviations_reason_bucket_label(row.get(reason_col))
                        if reason_col and reason_col in d.columns
                        else ""
                    ),
                ),
                (
                    "",
                    _clean_display_str(row.get(notes_col_eff))
                    if notes_col_eff and notes_col_eff in d.columns
                    else "",
                ),
            ]
        )
        if "snapshot_date" in d.columns:
            sd = row.get("snapshot_date")
            try:
                sds = (
                    pd.Timestamp(sd).strftime("%d.%m.%Y")
                    if pd.notna(pd.to_datetime(sd, errors="coerce"))
                    else str(sd) if sd is not None else ""
                )
            except Exception:
                sds = str(sd) if sd is not None else ""
            cells.append(("", sds))

        row_csv = {}
        for i, h in enumerate(headers):
            if i < len(cells):
                ent = cells[i]
                if len(ent) == 4:
                    row_csv[h] = ent[1]
                elif len(ent) == 2:
                    row_csv[h] = ent[1]
                else:
                    row_csv[h] = ent[1] if len(ent) > 1 else ""
        rows_out.append(row_csv)
        cells_rows.append(cells)

    return headers, rows_out, cells_rows


def build_deviations_reasons_full_table_export_df(
    table_reason_df, notes_col=None
) -> pd.DataFrame:
    """Тот же набор колонок и форматирование, что у CSV «deviations_detail» в отчёте."""
    headers, rows_out, _cells = _deviations_full_table_build(table_reason_df, notes_col)
    if not headers:
        return pd.DataFrame()
    return pd.DataFrame(rows_out, columns=headers)


def build_deviations_maket_export_df(
    table_reason_df, building_col=None, notes_col=None
) -> pd.DataFrame:
    """Строки таблицы по макету (ур. 5, причина, отклонение окончания < 0) — как выгрузка maket."""
    maket_df = _deviations_maket_prepare_df(table_reason_df)
    if maket_df.empty:
        return pd.DataFrame()
    notes_col_m = (
        notes_col
        if notes_col and notes_col in maket_df.columns
        else _find_column_by_keywords(
            maket_df, ("note", "заметк", "comment", "remark", "notes")
        )
    )
    _id_col_m = _deviations_maket_task_id_col(maket_df)
    _maket_out = []
    for _, rr in maket_df.iterrows():
        fb = _clean_display_str(rr.get("block")) if "block" in maket_df.columns else ""
        if not fb and "_dt_lvl2_key" in maket_df.columns:
            fb = _clean_display_str(rr.get("_dt_lvl2_key"))
        stv = _clean_display_str(rr.get("_dt_lvl3_key")) if "_dt_lvl3_key" in maket_df.columns else ""
        if not stv and building_col and building_col in maket_df.columns:
            stv = _clean_display_str(rr.get(building_col))
        pe = rr.get("plan end")
        be = rr.get("base end")
        ed = rr.get("_end_diff")
        tid = ""
        if _id_col_m and _id_col_m in maket_df.columns:
            _raw_id = rr.get(_id_col_m)
            if pd.notna(_raw_id) and str(_raw_id).strip() not in ("", "nan", "none"):
                tid = str(_raw_id).strip()
        _maket_out.append(
            {
                "ID задачи": tid,
                "Проект": _clean_display_str(rr.get("project name")),
                "Функциональный блок": fb,
                "Строение": stv,
                "Базовое окончание": be.strftime("%d.%m.%Y") if pd.notna(be) else "",
                "Окончание": pe.strftime("%d.%m.%Y") if pd.notna(pe) else "",
                "Отклонение": int(round(float(ed), 0)) if pd.notna(ed) else "",
                "Причина отклонения": _clean_display_str(rr.get("reason of deviation")),
                "Заметки": (
                    _clean_display_str(rr.get(notes_col_m))
                    if notes_col_m and notes_col_m in maket_df.columns
                    else ""
                ),
            }
        )
    return pd.DataFrame(_maket_out)


def _render_deviations_maket_table(
    table_reason_df,
    building_col=None,
    notes_col=None,
    *,
    file_stem: str = "deviations_detail_maket",
    key_prefix: str = "devtable_maket",
):
    """Таблица по макету: ур. 5, причина, отклонение окончания < 0."""
    notes_col_m = (
        notes_col
        if notes_col
        else _find_column_by_keywords(
            table_reason_df, ("note", "заметк", "comment", "remark", "notes")
        )
    )
    maket_df = _deviations_maket_prepare_df(table_reason_df)
    _id_col_m = _deviations_maket_task_id_col(maket_df)

    if maket_df.empty:
        st.info(
            "По макету нет строк: уровень 5, непустая причина, отклонение окончания < 0."
        )
        return

    _date_bg_m = _DEV_MAKET_COL_BG
    _date_cell_st = f' style="background:{_date_bg_m};color:#0b1f33;"'
    _maket_wrap_id = f"dev_reason_maket_{abs(id(maket_df))}"
    _hdrs = [
        "ID задачи",
        "Проект",
        "Функциональный блок",
        "Строение",
        "Базовое окончание",
        "Окончание",
        "Отклонение",
        "Причина отклонения",
        "Заметки",
    ]
    _bg_hdrs = {"Базовое окончание", "Окончание", "Отклонение"}
    _tbl_m = [
        f'<div id="{_maket_wrap_id}" class="pred-detail-wrap rendered-table-wrap dev-maket-table-wrap" data-bi-rows="{len(maket_df)}">',
        '<table class="rendered-table bi-sortable-table bi-sort-click-only dev-maket-table" style="border-collapse:collapse;width:100%">',
        "<thead><tr>",
    ]
    for h in _hdrs:
        if h in _bg_hdrs:
            _hst = f' style="background:{_date_bg_m};color:#f5f5f5;"'
            _hcls = ' class="dev-mak-col-date"'
        elif h == "Проект":
            _hst = ""
            _hcls = ' class="dev-mak-col-proj"'
        else:
            _hst = ""
            _hcls = ""
        _tbl_m.append(f"<th{_hcls}{_hst}>{html_module.escape(h)}</th>")
    _tbl_m.append("</tr></thead><tbody>")

    for _, rr in maket_df.iterrows():
        pr = _clean_display_str(rr.get("project name"))
        fb = _clean_display_str(rr.get("block")) if "block" in maket_df.columns else ""
        if not fb and "_dt_lvl2_key" in maket_df.columns:
            fb = _clean_display_str(rr.get("_dt_lvl2_key"))
        stv = _clean_display_str(rr.get("_dt_lvl3_key")) if "_dt_lvl3_key" in maket_df.columns else ""
        if not stv and building_col and building_col in maket_df.columns:
            stv = _clean_display_str(rr.get(building_col))
        pe = rr.get("plan end")
        be = rr.get("base end")
        ed = rr.get("_end_diff")
        be_s = be.strftime("%d.%m.%Y") if pd.notna(be) else ""
        pe_s = pe.strftime("%d.%m.%Y") if pd.notna(pe) else ""
        ed_s = str(int(round(float(ed), 0))) if pd.notna(ed) else ""
        rs = _clean_display_str(rr.get("reason of deviation"))
        nt = _clean_display_str(rr.get(notes_col_m)) if notes_col_m and notes_col_m in maket_df.columns else ""
        tid = ""
        if _id_col_m and _id_col_m in maket_df.columns:
            _raw_id = rr.get(_id_col_m)
            if pd.notna(_raw_id) and str(_raw_id).strip() not in ("", "nan", "none"):
                tid = str(_raw_id).strip()
        if pd.notna(ed):
            ev = float(pd.to_numeric(ed, errors="coerce"))
            _c_sp = "#ff5454" if ev < 0 else "#46d68a"
        else:
            _c_sp = "#e0e0e0"

        _tbl_m.append("<tr>")
        _tbl_m.append(f"<td>{html_module.escape(tid)}</td>")
        _tbl_m.append(f'<td class="dev-mak-col-proj">{html_module.escape(pr)}</td>')
        _tbl_m.append(f"<td>{html_module.escape(fb)}</td>")
        _tbl_m.append(f"<td>{html_module.escape(stv)}</td>")
        _tbl_m.append(f"<td{_date_cell_st}>{html_module.escape(be_s)}</td>")
        _tbl_m.append(f"<td{_date_cell_st}>{html_module.escape(pe_s)}</td>")
        if pd.isna(ed):
            _tbl_m.append(f"<td{_date_cell_st}>—</td>")
        else:
            _tbl_m.append(
                f'<td style="background:{_date_bg_m};color:#0b1f33;text-align:right">'
                f'<span style="color:{_c_sp}!important;font-weight:600">{html_module.escape(ed_s)}</span></td>'
            )
        _bk_tbl = _deviations_reason_bucket_label(rr.get("reason of deviation")) if "reason of deviation" in maket_df.columns else "Прочее"
        _clr_tbl = _deviations_reason_bucket_colors().get(str(_bk_tbl).strip(), "")
