# ==================== ГДРС: кэш тяжёлых загрузок ====================
from dashboards.gdrs_resursi import (
    _gdrs_cached_dannye_maps,
    _gdrs_cached_load_resursi,
    _gdrs_cached_plan_aggregate,
    _gdrs_paths_mtime_sig,
    _gdrs_plan_loader,
)


_gdrs_fragment = getattr(st, "fragment", None)


def _gdrs_dyn_nice_dtick(y_lo: float, y_hi: float, *, target_ticks: int = 5) -> float:
    """Шаг делений оси Y по масштабу данных (меньший шаг — заметнее динамика)."""
    import math

    span = max(float(y_hi) - float(y_lo), 1.0)
    raw = span / max(1, int(target_ticks))
    if raw <= 0:
        return 1.0
    mag = 10 ** math.floor(math.log10(raw))
    for mult in (1, 2, 2.5, 5, 10):
        step = mult * mag
        if span / step <= target_ticks + 1:
            return float(step)
    return float(raw)


def _gdrs_dyn_y_range(series, *, pad_ratio: float = 0.14, min_pad: float = 8.0) -> list[float]:
    vals = pd.to_numeric(series, errors="coerce").fillna(0.0)
    if vals.empty:
        return [0.0, 1.0]
    y_lo = float(vals.min())
    y_hi = float(vals.max())
    y_span = max(y_hi - y_lo, 1.0)
    y_pad = max(y_span * pad_ratio, min_pad)
    return [max(0.0, y_lo - y_pad), y_hi + y_pad]


def _gdrs_dyn_panel_dtick(
    y_lo: float,
    y_hi: float,
    agg_kind: str,
    *,
    series_kind: str = "fact",
) -> float:
    """Оптимальный шаг сетки Y для «День» / «Неделя» / «Месяц» / «Год» и ряда план/факт."""
    span = max(float(y_hi) - float(y_lo), 1.0)
    _agg = str(agg_kind or "").casefold()
    _sk = "plan" if str(series_kind).casefold().startswith("plan") else "fact"
    _presets = {
        "день": {"plan": (10, 0.08), "fact": (12, 0.10)},
        "неделя": {"plan": (12, 0.06), "fact": (14, 0.08)},
        "месяц": {"plan": (14, 0.05), "fact": (14, 0.06)},
        "год": {"plan": (10, 0.07), "fact": (12, 0.08)},
    }
    _target, _max_frac = _presets.get(_agg, _presets["день"])[_sk]
    _step = _gdrs_dyn_nice_dtick(y_lo, y_hi, target_ticks=_target)
    _cap = max(span * _max_frac, 1.0)
    if span <= 25:
        _cap = min(_cap, max(1.0, span / 5.0))
    elif span <= 60:
        _cap = min(_cap, max(2.0, span / 7.0))
    elif span <= 150:
        _cap = min(_cap, max(3.0, span / 9.0))
    return float(min(_step, _cap))


def _gdrs_dyn_panel_y_range(series, agg_kind: str) -> list[float]:
    """Узкий диапазон Y вокруг min/max — чтобы была видна динамика, не «пол» 0…max."""
    _agg = str(agg_kind or "").casefold()
    if _agg in ("неделя", "месяц", "год"):
        return _gdrs_dyn_y_range(series, pad_ratio=0.05, min_pad=2.0)
    return _gdrs_dyn_y_range(series, pad_ratio=0.08, min_pad=4.0)


def _gdrs_dynamics_chart_panel(
    fact_dyn,
    dyn_from_iso: str,
    dyn_to_iso: str,
    dog_sig: tuple,
    spr_sig: tuple,
    plan_col: str,
    sel_vid: str,
    dyn_title: str,
    vid_locked: str | None,
    month_periods: list | None = None,
    term_index=None,
    *,
    theme: str = "dark",
):
    """Линейный график динамики — fragment: смена группировки без полной перезагрузки страницы."""
    import plotly.graph_objects as _go
    from dashboards.gdrs_resursi import gdrs_dynamics_build_series
    from dashboards.gdrs_theme import (
        apply_gdrs_chart_background,
        get_gdrs_theme,
        gdrs_render_subheader,
        gdrs_apply_grouped_bar_labels,
        gdrs_apply_bar_outside_labels,
        gdrs_sanitize_bar_text_labels,
        inject_gdrs_light_preview_css,
    )

    _th = get_gdrs_theme(theme)

    dyn_from = pd.Timestamp(dyn_from_iso)
    dyn_to = pd.Timestamp(dyn_to_iso)
    if theme == "light":
        inject_gdrs_light_preview_css(st)
    gdrs_render_subheader(st, dyn_title, theme=theme)
    _agg_options = ["День", "Неделя", "Месяц"]
    _agg_key = f"gdrs_dyn_kind_{vid_locked or 'any'}_{theme}"
    if st.session_state.get(_agg_key) not in _agg_options:
        st.session_state[_agg_key] = "День"
    agg_kind = st.radio(
        "Группировка", _agg_options, horizontal=True,
        key=_agg_key,
    )
    st.caption(
        f"По всем загруженным датам: **{dyn_from.strftime('%d.%m.%Y')} — "
        f"{dyn_to.strftime('%d.%m.%Y')}** "
        f"(по выбранным месяцам в фильтре «Месяц»). "
        f"План и факт — **среднее за день** в выбранном периоде группировки."
    )
    uniq_pairs = fact_dyn[
        ["project_id", "project_name", "contractor_id", "contractor_name"]
    ].drop_duplicates()
    with st.spinner("Строим график динамики…"):
        dyn = gdrs_dynamics_build_series(
            fact_dyn, dyn_from, dyn_to, agg_kind,
            [], [], uniq_pairs, plan_col,
            plan_aggregate_loader=_gdrs_plan_loader(dog_sig, spr_sig),
            month_periods=month_periods,
            term_index=term_index,
        )
    if len(dyn) < 2:
        st.warning(
            "Для выбранной группировки доступен только один период. "
            "Выберите другую гранулярность или загрузите CSV за несколько месяцев."
        )
    try:
        _x = dyn["bucket"]
        _plan_s = pd.to_numeric(dyn["План"], errors="coerce").fillna(0.0)
        _fact_s = pd.to_numeric(dyn["Факт"], errors="coerce").fillna(0.0)
        _zero_plan_mask = _plan_s <= 0
        _zero_plan_n = int(_zero_plan_mask.sum())
        if _zero_plan_n > 0:
            _zdates = dyn.loc[_zero_plan_mask, "Период"].astype(str).tolist()
            _preview = ", ".join(_zdates[:5])
            _more = f" и ещё {_zero_plan_n - 5}" if _zero_plan_n > 5 else ""
            _fact_at_zero = int((_zero_plan_mask & (_fact_s > 0)).sum())
            _hint = (
                f" При этом в {_fact_at_zero} период(ах) факт > 0 — вероятна проблема с 1С "
                "(Dogovor / spravochniki на дату snapshot)."
                if _fact_at_zero > 0
                else " Проверьте загрузку Dogovor / spravochniki на даты snapshot."
            )
            st.warning(
                f"В {_zero_plan_n} период(ах) план из 1С равен 0 или отсутствует"
                f" ({_preview}{_more}).{_hint} "
                "На графике такие точки не соединяются линией плана."
            )

        _plan_plot = _plan_s.astype(float).copy()
        _plan_plot.loc[_zero_plan_mask] = np.nan

        _pct_hover = [
            f"{int(round(float(f) / float(p) * 100))}% от плана"
            if float(p) > 0
            else "—"
            for f, p in zip(_fact_s, _plan_s)
        ]
        _n_pts = len(dyn)
        _lbl_sz = 12 if _n_pts <= 12 else (11 if _n_pts <= 20 else (10 if _n_pts <= 32 else 9))
        _ann_sz = 11 if _n_pts <= 16 else 9

        _plan_for_range = _plan_plot.dropna()
        if _plan_for_range.empty:
            _plan_for_range = _plan_s
        _both = pd.concat([_plan_for_range, _fact_s], ignore_index=True)
        _comb_range = _gdrs_dyn_panel_y_range(_both, agg_kind)
        _comb_dtick = _gdrs_dyn_panel_dtick(
            _comb_range[0], _comb_range[1], agg_kind, series_kind="fact"
        )

        fig = _go.Figure()
        fig.add_trace(
            _go.Scatter(
                x=_x,
                y=_plan_plot,
                mode="lines+markers+text",
                line=dict(color=_th.line_plan, width=2.5),
                marker=dict(size=8),
                name="План",
                connectgaps=False,
                text=[
                    f"{int(v)}" if pd.notna(v) and float(v) > 0 else ""
                    for v in _plan_plot
                ],
                textposition="top center",
                textfont=dict(color=_th.line_plan, size=_lbl_sz),
                cliponaxis=False,
                hovertemplate="План: %{y}<br>%{x|%d.%m.%Y}<extra></extra>",
            )
        )
        fig.add_trace(
            _go.Scatter(
                x=_x,
                y=dyn["Факт"],
                mode="lines+markers+text",
                line=dict(color=_th.line_fact, width=3),
                marker=dict(size=9),
                name="Факт",
                text=["" for _ in dyn["Факт"]],
                textposition="bottom center",
                textfont=dict(color=_th.line_fact, size=_lbl_sz),
                cliponaxis=False,
                customdata=_pct_hover,
                hovertemplate="Факт: %{y}<br>%{customdata}<br>%{x|%d.%m.%Y}<extra></extra>",
            )
        )
        for _xb, _f, _p in zip(_x, dyn["Факт"], dyn["План"]):
            _pct_color = _th.good if int(_p) > 0 and float(_f) >= float(_p) else _th.bad
            if int(_p) <= 0:
                _ann_text = f"{int(_f)}"
            else:
                _pct = int(round(float(_f) / float(_p) * 100.0))
                _ann_text = f"{int(_f)} ({_pct}%)"
            fig.add_annotation(
                x=_xb,
                y=int(_f),
                text=_ann_text,
                showarrow=False,
                xref="x",
                yref="y",
                xanchor="center",
                yanchor="top",
                yshift=-14 if _n_pts <= 16 else -10,
                font=dict(size=_ann_sz, color=_pct_color),
            )

        _base_h = max(520, min(760, 38 * _n_pts + 120))
        _chart_h = int(1.5 * _base_h)

        _x_dtick = None
        if str(agg_kind).casefold() == "день":
            if _n_pts > 24:
                _x_dtick = "D5"
            elif _n_pts > 12:
                _x_dtick = "D3"
            else:
                _x_dtick = "D2"
        elif str(agg_kind).casefold() == "неделя":
            _x_dtick = "D7"

        fig.update_layout(
            title=f"Среднее за день — {sel_vid.lower()} (ресурсы)",
            plot_bgcolor=_th.chart_bg,
            paper_bgcolor=_th.chart_bg,
            font_color=_th.text,
            height=_chart_h,
            margin=dict(l=62, r=32, t=104, b=96),
            legend=dict(orientation="h", yanchor="bottom", y=1.02, xanchor="left", x=0),
            yaxis=dict(
                title="Среднее за день",
                range=_comb_range,
                dtick=_comb_dtick,
                autorange=False,
                showgrid=True,
                gridcolor=_th.chart_grid,
            ),
        )
        fig.update_xaxes(
            title_text=f"Период — {agg_kind.lower()}",
            type="date",
            tickformat="%d.%m.%Y",
            dtick=_x_dtick,
            tickangle=-35 if _n_pts > 6 else 0,
            showgrid=True,
            gridcolor=_th.chart_grid,
        )
        fig = apply_gdrs_chart_background(fig, _th)
        st.plotly_chart(fig, use_container_width=True)
        st.caption(
            "План и факт на одной шкале (среднее за день в периоде группировки); "
            "подписи у факта — значение и % от плана."
        )

        _dyn_tbl = pd.DataFrame({
            "Период": dyn["Период"].astype(str),
            "План": _plan_s.round(0).astype(int),
            "Факт": _fact_s.round(0).astype(int),
        })
        _dyn_tbl["Отклонение"] = (_fact_s - _plan_s).round(0).astype(int)
        _dyn_tbl["Отклонение %"] = [
            ((float(f) - float(p)) / float(p) * 100.0)
            if float(p) > 0
            else float("nan")
            for f, p in zip(_fact_s, _plan_s)
        ]
        gdrs_render_subheader(st, "Детализация по периодам", theme=theme, level=4)
        render_report_html_table(
            _gdrs_summary_table_to_html(_dyn_tbl, theme=theme),
            export_df=_dyn_tbl,
            file_stem=_export_file_stem("Детализация по периодам"),
            key_prefix=f"gdrs_dyn_detail_{abs(id(_dyn_tbl))}",
        )
    except Exception as _e:
        st.warning(f"Plotly недоступен: {_e}")
        _plan_fb = pd.to_numeric(dyn["План"], errors="coerce").fillna(0.0)
        _fact_fb = pd.to_numeric(dyn["Факт"], errors="coerce").fillna(0.0)
        _fb_tbl = pd.DataFrame({
            "Период": dyn["Период"],
            "План": _plan_fb.round(0).astype(int),
            "Факт": _fact_fb.round(0).astype(int),
        })
        _fb_tbl["Отклонение"] = (_fact_fb - _plan_fb).round(0).astype(int)
        _fb_tbl["Отклонение %"] = [
            ((float(f) - float(p)) / float(p) * 100.0)
            if float(p) > 0
            else float("nan")
            for f, p in zip(_fact_fb, _plan_fb)
        ]
        render_report_html_table(
            _gdrs_summary_table_to_html(_fb_tbl, theme=theme),
            export_df=_fb_tbl,
            file_stem=_export_file_stem("Детализация по периодам"),
            key_prefix=f"gdrs_dyn_detail_fb_{abs(id(_fb_tbl))}",
        )


# ==================== DASHBOARD: ГДРС (новая реализация по ТЗ 2026-05-07) ====================
def _gdrs_projects_summary_display(proj_df: pd.DataFrame) -> pd.DataFrame:
    d = proj_df.sort_values("plan", ascending=False).copy()
    out = pd.DataFrame({
        "Проект": d["project_name"].astype(str),
        "План": d["plan"].fillna(0).round(0).astype(int),
        "Факт": d["skud"].fillna(0).round(0).astype(int),
        "Отклонение": d["deviation"].round(0).astype(int),
    })
    if "delta_pct" in d.columns:
        out["Отклонение %"] = d["delta_pct"]
    return out


def _gdrs_build_contractors_chart_df(main_t: pd.DataFrame) -> pd.DataFrame:
    """Свод по контрагентам: одна строка на контрагента (без дублей по проектам)."""
    cols = ["project_name", "contractor_name", "plan", "skud"]
    raw = main_t.loc[main_t["row_kind"] == "row", [c for c in cols if c in main_t.columns]].copy()
    if raw.empty or "contractor_name" not in raw.columns:
        return pd.DataFrame(columns=["Контрагент", "План", "Факт", "Отклонение"])
    if "project_name" in raw.columns:
        raw = raw.drop_duplicates(subset=["project_name", "contractor_name"], keep="first")
    raw["contractor_name"] = raw["contractor_name"].astype(str).str.strip()
    raw = raw[raw["contractor_name"] != ""]
    if raw.empty:
        return pd.DataFrame(columns=["Контрагент", "План", "Факт", "Отклонение"])
    raw["plan"] = pd.to_numeric(raw["plan"], errors="coerce").fillna(0.0)
    raw["skud"] = pd.to_numeric(raw["skud"], errors="coerce").fillna(0.0)
    agg = raw.groupby("contractor_name", as_index=False).agg(
        plan=("plan", "sum"),
        skud=("skud", "sum"),
    )
    agg.rename(
        columns={"contractor_name": "Контрагент", "plan": "План", "skud": "Факт"},
        inplace=True,
    )
    agg["План"] = agg["План"].round(0).astype(int)
    agg["Факт"] = agg["Факт"].round(0).astype(int)
    agg["Отклонение"] = (agg["Факт"] - agg["План"]).round(0).astype(int)
    return agg.sort_values("План", ascending=False).reset_index(drop=True)


def _gdrs_contractors_summary_display(chart_df: pd.DataFrame) -> pd.DataFrame:
    d = chart_df.sort_values("План", ascending=False).copy()
    return d[["Контрагент", "План", "Факт", "Отклонение"]].copy()



def _gdrs_pie_distribution_display(pie_df: pd.DataFrame) -> pd.DataFrame:
    d = pie_df.sort_values("Факт", ascending=False).copy()
    total = float(pd.to_numeric(d["Факт"], errors="coerce").fillna(0).sum())
    out = pd.DataFrame({
        "Контрагент": d["Контрагент"].astype(str),
    })
    if "План" in d.columns:
        out["План"] = pd.to_numeric(d["План"], errors="coerce").fillna(0).round(0).astype(int)
    out["Факт"] = pd.to_numeric(d["Факт"], errors="coerce").fillna(0).round(0).astype(int)
    if "Отклонение" in d.columns:
        out["Отклонение"] = pd.to_numeric(d["Отклонение"], errors="coerce").fillna(0).round(0).astype(int)
    if total > 0:
        out["Доля, %"] = (
            pd.to_numeric(d["Факт"], errors="coerce").fillna(0) / total * 100.0
        ).apply(lambda x: f"{float(x):.1f}%")
    else:
        out["Доля, %"] = "—"
    return out


def _gdrs_deviation_vs_plan_text_and_color(plan_v, fact_v) -> tuple[str, str]:
    """Подпись отклонения (факт − план): факт < план — красный и «−», иначе зелёный и «+»."""
    p = float(pd.to_numeric(plan_v, errors="coerce") or 0)
    f = float(pd.to_numeric(fact_v, errors="coerce") or 0)
    d = int(round(f - p))
    if f < p:
        return f"{d:d}", "#ff5454"
    if f > p:
        return f"{d:+d}", "#46d68a"
    return "0", "#8899aa"


def _gdrs_deviation_display_cls(v) -> tuple[str, str]:
    """Отклонение = факт − план: «+» если факт > плана, «−» если наоборот."""
    fv = pd.to_numeric(v, errors="coerce")
    if pd.isna(fv):
        return "—", ""
    d = int(round(float(fv)))
    if d < 0:
        return f"{d:d}", "gdrs-u"
    if d > 0:
        return f"{d:+d}", "gdrs-o"
    return "0", "gdrs-z"


def _gdrs_pct_display_cls(v) -> tuple[str, str]:
    if isinstance(v, str) and "%" in v:
        try:
            fv = float(str(v).replace("%", "").replace(",", ".").strip())
        except (TypeError, ValueError):
            return str(v), ""
    else:
        fv = pd.to_numeric(v, errors="coerce")
    if pd.isna(fv):
        return "—", ""
    display = float(fv)
    text_v = f"{display:+.1f}%" if display != 0.0 else "0.0%"
    if display < 0:
        return text_v, "gdrs-u"
    if display > 0:
        return text_v, "gdrs-o"
    return text_v, "gdrs-z"


def _gdrs_deviation_cell_bg_style(raw) -> str:
    """Фон «Отклонение» (План − Факт): >0 красный, <0 зелёный."""
    from dashboards.gdrs_resursi import gdrs_deviation_cell_bg_style

    return gdrs_deviation_cell_bg_style(raw)


def _gdrs_summary_table_to_html(df: pd.DataFrame, *, theme: str = "dark") -> str:
    from dashboards.gdrs_theme import get_gdrs_theme

    _th = get_gdrs_theme(theme)
    if df is None or df.empty:
        return "<p>Нет данных для отображения.</p>"
    wrap_id = "gdrs_sum_" + str(abs(id(df)))
    tag = "d" + "iv"
    _wrap_cls = "gdrs-summary-table-wrap gdrs-light-table" if _th.name == "light" else "gdrs-summary-table-wrap"
    parts = [
        f"<{tag} id=\"{wrap_id}\" class=\"{_wrap_cls}\" "
        f"style=\"overflow-x:auto;min-width:0;margin:0.75em 0;\">",
        f"<style>"
        f"#{wrap_id} table {{ width:100%; table-layout:fixed; border-collapse:collapse; font-size:15px; "
        f"background-color:{_th.table_bg}; color:{_th.table_text}; }}"
        f"#{wrap_id} th.col-num, #{wrap_id} td.col-num {{ width:6.5rem; min-width:5rem; max-width:7.5rem; white-space:nowrap!important; }}"
        f"#{wrap_id} th.col-text, #{wrap_id} td.col-text {{ width:auto; min-width:9rem; }}"
        f"#{wrap_id} th, #{wrap_id} td {{ border:1px solid {_th.border}; padding:8px 10px; color:{_th.table_text} !important; font-weight:700; }}"
        f"#{wrap_id} th, #{wrap_id} td, #{wrap_id} th *, #{wrap_id} td * {{ color:{_th.table_text} !important; }}"
        f"#{wrap_id} th {{ background-color:{_th.table_header_bg}; {_th.table_header_font_css}; text-align:center!important; white-space:normal;word-wrap:break-word;overflow-wrap:anywhere;line-height:1.25;max-width:11em;overflow:visible;text-overflow:clip;vertical-align:bottom; }}"
        f"#{wrap_id} td {{ text-align:center;vertical-align:middle;white-space:normal;word-wrap:break-word;overflow-wrap:anywhere;overflow:visible;text-overflow:clip;max-width:28em; }}"
        f"#{wrap_id} td.col-text {{ text-align:left!important;vertical-align:top;max-width:36em; }}"
        f"#{wrap_id} th.col-text {{ text-align:center!important; }}"
        f"#{wrap_id} td.gdrs-u, #{wrap_id} td.gdrs-u span {{ color:{_th.bad} !important; font-weight:800; }}"
        f"#{wrap_id} td.gdrs-o, #{wrap_id} td.gdrs-o span {{ color:{_th.good} !important; font-weight:800; }}"
        f"#{wrap_id} td.gdrs-z, #{wrap_id} td.gdrs-z span {{ color:{_th.neutral} !important; }}"
        f"</style>",
        '<table class="bi-sortable-table"><thead><tr>',
    ]
    for col in df.columns:
        _cc = table_column_css_class(str(col))
        _ce = html_module.escape(str(col))
        parts.append(
            f'<th class="{_cc}" data-sort-label="{_ce}">'
            f'<span class="bi-sort-label">{_ce} \u21c5</span></th>'
        )
    parts.append("</tr></thead><tbody>")
    _int_cols = {"План", "Факт", "СКУД"}
    for _, row in df.iterrows():
        parts.append("<tr>")
        for col in df.columns:
            val = row[col]
            cl = str(col).strip()
            extra_cls = ""
            extra_style = ""
            if cl == "Отклонение":
                inner, extra_cls = _gdrs_deviation_display_cls(val)
                extra_style = _gdrs_deviation_cell_bg_style(val)
            elif cl == "Отклонение %":
                inner, extra_cls = _gdrs_pct_display_cls(val)
                extra_style = _gdrs_delta_pct_cell_bg_style(val)
            elif cl in _int_cols:
                num = pd.to_numeric(val, errors="coerce")
                inner = "0" if pd.isna(num) else str(int(round(float(num))))
            else:
                inner = "" if val is None or (isinstance(val, float) and pd.isna(val)) else str(val)
            _cc = table_column_css_class(cl)
            _td_cls = f"{_cc} {extra_cls}".strip() if extra_cls else _cc
            cls_attr = f' class="{_td_cls}"' if _td_cls else ""
            st_attr = f' style="{extra_style}"' if extra_style else ""
            parts.append(f"<td{cls_attr}{st_attr}><span>{html_module.escape(inner)}</span></td>")
        parts.append("</tr>")
    parts.append(f"</tbody></table></{tag}>")
    return mark_html_table_sortable("".join(parts))

def _gdrs_render_plan_fact_summary_table(
    st,
    display_df: pd.DataFrame,
    *,
    table_title: str,
    theme: str = "dark",
) -> None:
    from dashboards.gdrs_theme import gdrs_render_table_subheader

    if display_df is None or display_df.empty:
        st.info("Нет данных для таблицы.")
        return
    gdrs_render_table_subheader(st, table_title, theme=theme)
    render_report_html_table(
        _gdrs_summary_table_to_html(display_df, theme=theme),
        export_df=display_df,
        file_stem=_export_file_stem(table_title),
        key_prefix=f"gdrs_sum_{abs(id(display_df))}",
    )


