def dashboard_gdrs(df, vid_locked: str | None = None, *, theme: str = "dark"):
    """
    ГДРС — переписанный по ТЗ заказчика 2026-05-07 (см. docs/TZ_GDRS_2026-05-07.md).

    Параметры:
        vid_locked: "Рабочие" / "Техника" / None.
            Если задан — radio-фильтр «Вид ресурсов» скрывается, дашборд работает в этом режиме
            (используется обёртками dashboard_gdrs_people / dashboard_gdrs_equipment_v2).

    Источники:
      • web/AI/other_<DD-MM-YYYY>_resursi.csv  → план/факт по неделям, по контрагентам.
      • web/1с_*_Dogovor.json (все snapshot)   → план (Количество_Людей / Количество_Техники)
                                                 + Наименование_Договора (для «Вид работы»).
      • web/1с_*_spravochniki.json (все)       → fallback план (КоличествоРаботников / СпецТехники).

    UI: одна страница — 4 визуала (проекты, контрагенты, динамика, круговая) и таблица.
    Фильтры сверху: Проект (multi), Контрагент (multi), [Вид ресурсов — только если не locked],
                    Период (date range), «Только с планом» (checkbox).

    theme: "dark" (основной ГДРС) или "light" (отдельное превью для заказчика).
    """
    import os
    import sys
    from pathlib import Path as _Path
    import pandas as _pd
    import numpy as _np
    from dashboards.gdrs_theme import (
        apply_gdrs_chart_background,
        get_gdrs_theme,
        gdrs_deviation_vs_plan_text_and_color,
        gdrs_render_subheader,
        gdrs_render_table_subheader,
        gdrs_apply_grouped_bar_labels,
        gdrs_apply_bar_outside_labels,
        gdrs_sanitize_bar_text_labels,
        inject_gdrs_light_preview_css,
    )

    _th = get_gdrs_theme(theme)
    if theme == "light":
        inject_gdrs_light_preview_css(st)
        _gdrs_light_preview_active = True
    else:
        _gdrs_light_preview_active = False

    _this = os.path.dirname(os.path.abspath(__file__))
    _root = os.path.dirname(_this)
    if _root not in sys.path:
        sys.path.insert(0, _root)
    from dashboards.gdrs_resursi import (
        build_main_table,
        gdrs_agg_label_to_key,
        gdrs_agg_select_options,
        gdrs_filter_fact_by_months,
        gdrs_matrix_show_week_columns,
        gdrs_matrix_week_labels,
        build_gdrs_audit_export_frames,
        gdrs_month_select_options,
        gdrs_default_month_labels,
        gdrs_resolve_month_periods,
        gdrs_months_date_range,
        gdrs_plan_snapshot_date,
        load_1c_dannye_article_maps,
        load_plan_aggregate,
        load_resursi_files,
        load_1c_kontr_index,
        enrich_gdrs_fact_contractor_ids,
        enrich_gdrs_fact_project_ids,
        gdrs_filter_fact_kontr_intersection,
        load_gdrs_termination_index,
        gdrs_filter_fact_by_termination,
        week_end_in_filtered_fact,
        _gdrs_plan_loader,
        gdrs_contractor_filter_options,
    )

    web_dir = _Path(_root) / "web"
    ai_dir = web_dir / "AI"

    resursi_files = sorted(ai_dir.glob("*resursi*.csv"))
    if not resursi_files:
        resursi_files = sorted(web_dir.glob("*resursi*.csv"))
    dogovor_files = sorted(web_dir.glob("*_Dogovor.json"))
    sprav_files = sorted(web_dir.glob("*_spravochniki.json"))
    kontr_files = sorted(web_dir.glob("*_Kontr.json"))

    if not resursi_files:
        st.warning(
            "Не найдены файлы ресурсов «other_*_resursi.csv» в папке web/AI. "
            "Загрузите ресурсный CSV через ETL или поместите в web/AI."
        )
        return

    _res_sig = _gdrs_paths_mtime_sig(resursi_files)
    _dog_sig = _gdrs_paths_mtime_sig(dogovor_files)
    _spr_sig = _gdrs_paths_mtime_sig(sprav_files)

    with st.spinner("Загрузка ресурсов…"):
        long_fact = _gdrs_cached_load_resursi(_res_sig)
    if long_fact is None or long_fact.empty:
        st.error("Файлы ресурсов не распознаны (формат?). Проверьте структуру CSV.")
        return
    long_fact = apply_unified_project_column(long_fact, "project_name")
    _kontr_index = load_1c_kontr_index(kontr_files) if kontr_files else None
    long_fact = enrich_gdrs_fact_contractor_ids(
        long_fact,
        dogovor_paths=dogovor_files,
        kontr=_kontr_index,
    )
    long_fact = enrich_gdrs_fact_project_ids(
        long_fact,
        dogovor_paths=dogovor_files,
    )

    long_fact = gdrs_filter_fact_kontr_intersection(long_fact, _kontr_index)
    _term_index = load_gdrs_termination_index(dogovor_files)
    long_fact = gdrs_filter_fact_by_termination(long_fact, _term_index)

    _month_options = gdrs_month_select_options(
        long_fact,
        extra_paths=list(resursi_files) + list(dogovor_files),
    )
    _month_labels = [lbl for lbl, _ in _month_options]
    _month_label_to_period = {lbl: per for lbl, per in _month_options}

    use_radio = vid_locked is None
    _gdrs_vid_key = vid_locked or "any"
    _gdrs_key_suffix = f"{_gdrs_vid_key}_light" if theme == "light" else _gdrs_vid_key
    _gdrs_reset_keys = [
        f"gdrs_filter_projects_{_gdrs_key_suffix}",
        f"gdrs_filter_contractors_{_gdrs_key_suffix}",
        f"gdrs_filter_months_{_gdrs_key_suffix}",
        f"gdrs_filter_only_plan_{_gdrs_key_suffix}",
        f"gdrs_filter_plan_agg_{_gdrs_key_suffix}",
        f"gdrs_filter_skud_agg_{_gdrs_key_suffix}",
    ]
    if use_radio:
        _gdrs_reset_keys.append(f"gdrs_filter_vid_{_gdrs_key_suffix}")
    with filters_panel(st, reset_keys=_gdrs_reset_keys):
        project_options = project_labels_for_filter(long_fact["project_name"])
        _agg_opts = gdrs_agg_select_options()
        with filters_selectors(st):
            if use_radio:
                _fc1, _fc2, _fc3, _fc4, _fc5, _fc6 = st.columns(6, gap="small")
            else:
                _fc1, _fc2, _fc3, _fc4, _fc5 = st.columns(5, gap="small")
            with _fc1:
                sel_projects, _ = project_filter_multiselect(
                    st,
                    project_options,
                    key=f"gdrs_filter_projects_{_gdrs_key_suffix}",
                )
            _lf_proj = filter_dataframe_by_project_labels(
                long_fact, sel_projects, col="project_name"
            )
            _filter_plan_snap = (
                _pd.Timestamp(_month_label_to_period[_month_labels[-1]].end_time).normalize()
                if _month_labels
                else None
            )
            contractor_options = gdrs_contractor_filter_options(
                long_fact,
                dogovor_files,
                sprav_files,
                projects=sel_projects or None,
                snapshot_date=_filter_plan_snap,
            )
            with _fc2:
                sel_contractors = st.multiselect(
                    "Контрагент",
                    contractor_options,
                    default=[],
                    key=f"gdrs_filter_contractors_{_gdrs_key_suffix}",
                    help="Пусто = все контрагенты выбранных проектов",
                    placeholder="Выберите контрагентов",
                )
            if use_radio:
                with _fc3:
                    sel_vid = st.radio(
                        "Вид ресурсов",
                        ["Рабочие", "Техника"],
                        horizontal=True,
                        key=f"gdrs_filter_vid_{_gdrs_key_suffix}",
                    )
                _month_col = _fc4
                _plan_col = _fc5
                _skud_col = _fc6
            else:
                sel_vid = vid_locked
                _month_col = _fc3
                _plan_col = _fc4
                _skud_col = _fc5
            with _month_col:
                _default_months = gdrs_default_month_labels(_month_options, long_fact)
                migrate_gdrs_month_multiselect_state(
                    st,
                    f"gdrs_filter_months_{_gdrs_key_suffix}",
                    _month_labels,
                    default_labels=_default_months,
                )
                sel_month_labels = st.multiselect(
                    "Месяц",
                    _month_labels,
                    default=_default_months,
                    key=f"gdrs_filter_months_{_gdrs_key_suffix}",
                    placeholder="Все месяцы",
                    help="Один или несколько календарных месяцев. Пусто — все месяцы с данными.",
                )
            with _plan_col:
                _plan_lbl = st.selectbox(
                    "План",
                    _agg_opts,
                    index=0,
                    key=f"gdrs_filter_plan_agg_{_gdrs_key_suffix}",
                    help="Среднее за месяц — план из 1С на конец периода; "
                    "N неделя — план из 1С на последний день этой недели в периоде",
                )
            with _skud_col:
                _skud_lbl = st.selectbox(
                    "СКУД",
                    _agg_opts,
                    index=0,
                    key=f"gdrs_filter_skud_agg_{_gdrs_key_suffix}",
                    help="Среднее за месяц — среднее факт/день за весь период (CSV); "
                    "N неделя — среднее факт/день только в выбранной неделе",
                )

        with filters_toggles(st):
            only_with_plan = st.checkbox(
                "Только с планом",
                value=True,
                key=f"gdrs_filter_only_plan_{_gdrs_key_suffix}",
                help="Скрыть подрядчиков без плана в активном договоре",
            )


    _sel_periods, _month_stale = gdrs_resolve_month_periods(_month_options, sel_month_labels)
    if _month_stale:
        st.warning(
            "Выбранный месяц отсутствует в данных — показаны все доступные месяцы. "
            "Выберите период из списка (например, Февраль 2026)."
        )
    date_from, date_to = gdrs_months_date_range(_sel_periods)
    date_from = _pd.to_datetime(date_from)
    date_to = _pd.to_datetime(date_to)
    long_fact_period = gdrs_filter_fact_by_months(long_fact, _sel_periods)
    if (
        long_fact is not None
        and not long_fact.empty
        and (long_fact_period is None or long_fact_period.empty)
    ):
        _fact_periods = set(
            pd.to_datetime(long_fact["date"], errors="coerce").dt.to_period("M").dropna().unique()
        )
        _avail_labels = [lbl for lbl, per in _month_options if per in _fact_periods]
        _hint = (
            f" Доступные месяцы с фактом СКУД: {', '.join(_avail_labels[-6:])}."
            if _avail_labels
            else ""
        )
        st.warning(
            "За выбранный месяц нет фактических данных СКУД (план 1С может отображаться). "
            "Выберите период с загруженным фактом."
            + _hint
        )

    _plan_agg = gdrs_agg_label_to_key(_plan_lbl)
    _skud_agg = gdrs_agg_label_to_key(_skud_lbl)
    _plan_snap = gdrs_plan_snapshot_date(
        long_fact_period,
        vid=sel_vid,
        date_from=date_from,
        date_to=date_to,
        plan_agg=_plan_agg,
        projects=sel_projects or None,
        contractors=sel_contractors or None,
    )
    plan = _gdrs_cached_plan_aggregate(
        _dog_sig, _spr_sig, pd.Timestamp(_plan_snap).normalize().isoformat(),
    )

    _weekly_plan_by_week: dict[int, _pd.DataFrame] = {}
    _weekly_plan_as_of: dict[int, _pd.Timestamp] = {}
    if gdrs_matrix_show_week_columns(_plan_agg, _skud_agg, date_from=date_from, date_to=date_to):
        for _wn in range(1, 7):
            _w_end = week_end_in_filtered_fact(
                long_fact_period,
                vid=sel_vid,
                date_from=date_from,
                date_to=date_to,
                week_num=_wn,
                projects=sel_projects or None,
                contractors=sel_contractors or None,
            )
            if _w_end is None or not _pd.notna(_w_end):
                continue
            _weekly_plan_as_of[_wn] = _pd.Timestamp(_w_end).normalize()
            _weekly_plan_by_week[_wn] = _gdrs_cached_plan_aggregate(
                _dog_sig,
                _spr_sig,
                _weekly_plan_as_of[_wn].isoformat(),
            )

    _dannye_paths: list[_Path] = []
    for _base in (web_dir, ai_dir):
        if _base.is_dir():
            for _pat in ("*dannye*.json", "*Dannye*.json"):
                _dannye_paths.extend(_base.glob(_pat))
    _dannye_sig = _gdrs_paths_mtime_sig(
        sorted({_p.resolve() for _p in _dannye_paths if _p.is_file()})
    )
    _by_dog, _by_pc, _by_sig_pc, _by_sig, _by_pc_sets = _gdrs_cached_dannye_maps(_dannye_sig)

    main_t = build_main_table(
        long_fact_period, plan,
        vid=sel_vid,
        date_from=date_from, date_to=date_to,
        projects=sel_projects or None,
        contractors=sel_contractors or None,
        only_with_plan=only_with_plan,
        article_by_contract_norm=_by_dog if _by_dog else None,
        article_sig_pc_sets=_by_sig_pc if _by_sig_pc else None,
        article_sig_sets=_by_sig if _by_sig else None,
        article_by_project_contractor=_by_pc if _by_pc else None,
        article_pc_sets=_by_pc_sets if _by_pc_sets else None,
        plan_agg=_plan_agg,
        skud_agg=_skud_agg,
        weekly_plan_by_week=_weekly_plan_by_week or None,
        weekly_plan_as_of=_weekly_plan_as_of or None,
        kontr_index=_kontr_index,
        term_index=_term_index,
        plan_as_of=_pd.Timestamp(_plan_snap).normalize(),
        plan_aggregate_loader=_gdrs_plan_loader(_dog_sig, _spr_sig),
    )
    if main_t is None or main_t.empty:
        st.info("Нет данных для выбранных фильтров.")
        return

    period_label = (
        f"{date_from.strftime('%d.%m.%Y')} — {date_to.strftime('%d.%m.%Y')}"
        if date_from != date_to else date_from.strftime("%d.%m.%Y")
    )
    unit = "люди" if sel_vid == "Рабочие" else "техника"
    _unit_gen = "людей" if sel_vid == "Рабочие" else "техники"

    chart_df = _gdrs_build_contractors_chart_df(main_t)

    gdrs_render_subheader(st, "ГДРС по выбранным проектам", theme=theme)
    proj_df = main_t[main_t["row_kind"] == "subtotal"][
        ["project_name", "plan", "skud", "deviation", "delta_pct"]
    ].copy()
    if not proj_df.empty:
        try:
            import plotly.graph_objects as _go
            proj_df = proj_df.sort_values("plan", ascending=False).reset_index(drop=True)
            _proj_labels = proj_df["project_name"].astype(str).tolist()
            _plan_vals = proj_df["plan"].fillna(0).astype(int).tolist()
            _fact_vals = proj_df["skud"].fillna(0).astype(int).tolist()
            _dev_text, _dev_colors, _dev_abs = [], [], []
            for _pv, _fv in zip(proj_df["plan"], proj_df["skud"]):
                _lbl, _col = gdrs_deviation_vs_plan_text_and_color(_pv, _fv, _th)
                _dev_text.append(_lbl)
                _dev_colors.append(_col)
                _dev_abs.append(abs(int(round(float(_fv) - float(_pv)))))
            _bar_axis_sz = 22 if theme == "light" else 14
            _proj_x_tick_sz = 44 if theme == "light" else 34
            _bar_title_sz = 22 if theme == "light" else 16
            _bar_margin_b = 120 if theme == "light" else 100
            fig_pf = _go.Figure()
            _bar_x_labels, _bar_title_suffix = _gdrs_add_plan_fact_deviation_traces(
                fig_pf,
                _proj_labels,
                _plan_vals,
                _fact_vals,
                _dev_abs,
                _dev_colors,
                _th,
            )
            _metrics_axis = len(_proj_labels) == 1
            fig_pf.update_layout(
                title=dict(
                    text=f"План / Факт / Отклонение по проектам{_bar_title_suffix}",
                    font=dict(size=_bar_title_sz, color=_th.text, family="Inter, sans-serif"),
                    x=0.0, xanchor="left", y=0.96, yanchor="top",
                ),
                barmode="group",
                plot_bgcolor=_th.chart_bg,
                paper_bgcolor=_th.chart_bg,
                font_color=_th.text,
                xaxis=dict(
                    showgrid=False,
                    tickfont=dict(size=_proj_x_tick_sz, color=_th.text, family="Inter, sans-serif"),
                    tickangle=0,
                ),
                yaxis=dict(
                    showgrid=True,
                    gridcolor=_th.chart_grid,
                    tickfont=dict(size=_bar_axis_sz if theme == "light" else 12, color=_th.text),
                ),
                height=560 if theme == "light" else 520,
                margin=dict(l=56, r=24, t=88, b=_bar_margin_b),
                legend=dict(
                    orientation="h",
                    yanchor="bottom",
                    y=1.02,
                    xanchor="left",
                    x=0.0,
                    bgcolor="rgba(0,0,0,0)",
                ),
            )
            fig_pf = apply_gdrs_chart_background(fig_pf, _th, skip_uniformtext=True)
            # apply_gdrs_chart_background сбрасывает tickfont оси X — восстанавливаем крупные горизонтальные подписи проектов.
            fig_pf.update_xaxes(
                tickfont=dict(size=_proj_x_tick_sz, color=_th.text, family="Inter, sans-serif"),
                tickangle=0,
                ticklabelstandoff=14,
                automargin=True,
            )
            fig_pf.update_layout(margin=dict(l=56, r=24, t=88, b=_bar_margin_b))
            fig_pf = gdrs_apply_grouped_bar_labels(
                fig_pf,
                _th,
                _bar_x_labels,
                [
                    ([f"{v}" for v in _plan_vals], _th.bar_plan_text),
                    ([f"{v}" for v in _fact_vals], _th.bar_fact_text),
                    (_dev_text, _dev_colors),
                ],
            )
            fig_pf = _gdrs_apply_plan_fact_grouped_bar_spacing(
                fig_pf, len(_proj_labels), metrics_axis=_metrics_axis
            )
            st.plotly_chart(
                fig_pf,
                use_container_width=True,
                key=f"gdrs_proj_bar_{_gdrs_key_suffix}_{_plan_agg}_{_skud_agg}",
            )
        except Exception as _e:
            st.warning(f"Plotly недоступен: {_e}")
        _gdrs_render_plan_fact_summary_table(
            st,
            _gdrs_projects_summary_display(proj_df),
            table_title="ГДРС по выбранным проектам",
            theme=theme,
        )
    else:
        st.info("Нет данных по проектам.")

    gdrs_render_table_subheader(st, f"График движения рабочей силы ({unit}), {period_label}", theme=theme)
    period_days = max(1, (date_to - date_from).days + 1)
    if period_days > 45:
        st.warning(
            f"Выбран период {period_days} дн.: в таблице отображаются только первые 6 ISO-недель "
            f"({date_from.strftime('%d.%m.%Y')} — {(date_from + _pd.Timedelta(days=42)).strftime('%d.%m.%Y')}); "
            f"неделя 7+ не помещается в макет ТЗ. Сократите период до месяца, чтобы увидеть все недели."
        )
    _show_week_cols = gdrs_matrix_show_week_columns(
        _plan_agg, _skud_agg, date_from=date_from, date_to=date_to
    )
    if _show_week_cols:
        st.caption(
            "Колонки «План / СКУД / Отклонение» — **среднее за день за весь выбранный период**. "
            "Колонки «N нед» — порядковые ISO-недели **с начала периода** (1-я = самая ранняя неделя в фильтре); "
            "план по неделе — срез 1С на последний день этой недели в периоде (сумма по всем действующим договорам)."
        )
    view = main_t.copy()
    view["Контрагент"] = view.apply(
        lambda r: (
            r["project_name"] if r["row_kind"] == "subtotal"
            else ("Итого" if r["row_kind"] == "grand_total" else r["contractor_name"])
        ),
        axis=1,
    )
    if "vid_raboty" in view.columns:
        vid_col = view["vid_raboty"].fillna("").astype(str)
        view["Вид работ"] = [v if v.strip() else "—" for v in vid_col]
    else:
        view["Вид работ"] = view["contract_name"].fillna("").astype(str).apply(
            lambda s: s if s else "—"
        )
    view["План"] = view["plan"].fillna(0).round(0).astype(int)
    view["СКУД"] = view["skud"].fillna(0).round(0).astype(int)
    view["Отклонение"] = view["deviation"].round(0).astype(int)
    view["__kind__"] = view["row_kind"]
    view["_delta_pct_raw"] = view["delta_pct"]
    for _pk in ("p1", "p2", "p3", "p4", "p5", "p6"):
        if _pk in view.columns:
            view[_pk] = view[_pk].fillna(0).astype(int)
    for _wk in ("w1", "w2", "w3", "w4", "w5", "w6"):
        view[_wk] = view[_wk].fillna(0).astype(int)
    from dashboards.gdrs_resursi import render_gdrs_matrix_table_html
    _tbl_title = f"График движения рабочей силы ({unit})"
    _tbl_period = (
        _format_gdrs_month_year_title_ru(date_from, date_to, long_fact_period, None) or period_label
    )
    _week_ren = {
        "p1": "План 1 нед", "p2": "План 2 нед", "p3": "План 3 нед",
        "p4": "План 4 нед", "p5": "План 5 нед", "p6": "План 6 нед",
        "w1": "СКУД 1 нед", "w2": "СКУД 2 нед", "w3": "СКУД 3 нед",
        "w4": "СКУД 4 нед", "w5": "СКУД 5 нед", "w6": "СКУД 6 нед",
    }
    _mtx_drop = {
        "__kind__", "_delta_pct_raw", "row_kind", "project_name", "contractor_name",
        "contract_name", "vid_raboty", "plan", "skud", "deviation", "delta_pct",
    }
    _mtx_export = view.drop(columns=[c for c in view.columns if c in _mtx_drop], errors="ignore")
    _mtx_export = _mtx_export.rename(columns={k: v for k, v in _week_ren.items() if k in _mtx_export.columns})
    _week_hdr_labels = (
        gdrs_matrix_week_labels(date_from, date_to, long_fact_period["date"])
        if _show_week_cols
        else None
    )
    render_report_html_table(
        render_gdrs_matrix_table_html(
            view,
            fixed_cols=["Контрагент", "Вид работ", "План", "СКУД", "Отклонение"],
            delta_col="Отклонение %",
            kind_col="__kind__",
            title_line=_tbl_title,
            period_line=_tbl_period,
            delta_bg_style=_gdrs_delta_pct_cell_bg_style,
            show_week_columns=_show_week_cols,
            week_labels=_week_hdr_labels,
            theme=theme,
        ),
        export_df=_mtx_export,
        file_stem=_export_file_stem(_tbl_title),
        key_prefix=f"gdrs_matrix_{abs(id(view))}",
    )
