def calculate_forecast_budget(
    df,
    edited_data=None,
    distribution_mode="uniform",
    abc_source=None,
    row_modes: Optional[pd.Series] = None,
):
    """
    Прогноз БДДС по месяцам: «БДДС план» (сводка по MSP), «БДДС прогноз» (распределение),
    «БДДС факт» (распределение факта по тем же весам).
    """
    work_df = edited_data.copy() if edited_data is not None else df.copy()
    return compute_bddcs_forecast_monthly(
        work_df,
        distribution_mode=distribution_mode,
        abc_source=abc_source,
        row_modes=row_modes,
    )


def _forecast_find_turnover_dataframe():
    """Ищет в session_state DataFrame оборотов 1С (БДДС) по типичным ключам/колонкам."""
    try:
        d0 = st.session_state.get("reference_1c_dannye")
        if isinstance(d0, pd.DataFrame) and not getattr(d0, "empty", True):
            return d0
    except Exception:
        pass
    try:
        keys = list(st.session_state.keys())
    except Exception:
        keys = []
    preferred = (
        "budget_1c_data",
        "bddcs_1c",
        "bddcs_turnover",
        "project_budget_1c",
        "dannye_bddcs",
        "turnover_1c",
    )
    for k in preferred:
        if k in keys:
            d = st.session_state.get(k)
            if isinstance(d, pd.DataFrame) and not getattr(d, "empty", True):
                return d
    for k in keys:
        d = st.session_state.get(k)
        if not isinstance(d, pd.DataFrame) or getattr(d, "empty", True):
            continue
        joined = " ".join(str(c).casefold() for c in d.columns)
        if "сценар" in joined and ("сумм" in joined or "amount" in joined):
            if "стать" in joined or "article" in joined or "оборот" in joined:
                return d
    return None


def _forecast_is_lot_value(s) -> bool:
    """Признак «лота»: текст содержит «ЛОТ» либо начинается с числового обозначения (17.1, 01, 98 и т.п.)."""
    txt = _clean_display_str(s)
    if not txt:
        return False
    if "лот" in txt.casefold():
        return True
    return bool(re.match(r"^\s*\d", txt))


def _forecast_merge_bddcs_from_1c(project_df: pd.DataFrame, project_name: str) -> pd.DataFrame:
    """
    Подставляет суммы из оборотов 1С (БДДС):

    - **БДДС план**: сценарий «Бюджет»/«План», статья оборотов без «(БДР)».
    - **БДДС факт**: сценарий «Факт», те же ограничения по статье.
    - Учитываем только **лотовые статьи** оборотов (статья содержит «ЛОТ» или начинается с
      числового обозначения) и разносим суммы **по лоту** через ключ `ID_Лота` ↔ `ЛОТ_ID`.
      Сумма лота делится поровну между строками MSP этого лота (чтобы при агрегации по лоту
      получить исходный итог, а на уровне задач — корректные доли).
    - Фолбэк (нет лотовых сопоставлений): прежнее пропорциональное распределение по проекту.
    """
    bdf = _forecast_find_turnover_dataframe()
    if bdf is None or bdf.empty or project_df is None or project_df.empty:
        return project_df
    out = project_df.copy()

    def _col(df, needles):
        cols = {str(c).strip().casefold(): c for c in df.columns}
        for n in needles:
            k = str(n).strip().casefold()
            if k in cols:
                return cols[k]
        for c in df.columns:
            cl = str(c).casefold()
            for n in needles:
                if str(n).casefold() in cl:
                    return c
        return None

    scen = _col(bdf, ("Сценарий", "scenario"))
    art = _col(bdf, ("СтатьяОборотов", "Статья оборотов", "article"))
    amt = _col(bdf, ("Сумма", "amount"))
    proj = _col(bdf, ("Проект", "project"))
    typ = _col(bdf, ("ТипСтатьи", "article_type", "Тип статьи"))
    if not scen or not amt:
        return out

    t = bdf.copy()
    if proj:
        pn = _project_filter_norm_key(project_name)
        t["_pk"] = t[proj].map(_project_filter_norm_key)
        t = t[t["_pk"] == pn]
    if t.empty:
        return out

    def _no_bdr(row) -> bool:
        a = str(row.get(art, "") if art else "").casefold()
        if "(бдр)" in a or a.strip() == "бдр":
            return False
        if typ and typ in row.index:
            tl = str(row.get(typ, "")).casefold()
            if "бдр" in tl and "бддс" not in tl:
                return False
        return True

    t_base = t[t.apply(_no_bdr, axis=1)]
    if t_base.empty:
        return out

    t_bd = t_base
    if typ:
        _tls = t_base[typ].astype(str).str.casefold()
        _bdds_rows = _tls.str.contains("бддс", na=False)
        if bool(_bdds_rows.any()):
            t_bd = t_base.loc[_bdds_rows]
    if t_bd.empty:
        t_bd = t_base

    try:
        from dashboards.finance_from_1c import _amount_series_to_rubles
        amt_num = _amount_series_to_rubles(t_bd, amt)
    except Exception:
        amt_num = pd.to_numeric(t_bd[amt], errors="coerce").fillna(0.0)
    sser = t_bd[scen].astype(str)

    _norm_scen = sser.str.strip().str.casefold()
    budget_mask = sser.str.contains("бюджет", case=False, na=False) | sser.str.contains(
        "budget", case=False, na=False
    )
    plan_mask = budget_mask
    fact_mask = sser.str.contains("факт", case=False, na=False) | sser.str.contains(
        "fact", case=False, na=False
    ) | _norm_scen.eq("факт")

    if plan_mask.sum() == 0:
        legacy_plan_mask = (
            sser.str.contains("план", case=False, na=False)
            & ~sser.str.contains("факт", case=False, na=False)
        ) | _norm_scen.eq("план")
        if legacy_plan_mask.any():
            plan_mask = legacy_plan_mask

    plan_sum = float(amt_num.loc[plan_mask].sum())
    fact_sum = float(amt_num.loc[fact_mask].sum())

    # ── Разнос по лоту: только лотовые статьи, ключ ID_Лота ↔ ЛОТ_ID ──
    lotid_col = _col(t_bd, ("ID_Лота", "ID Лота", "ID_лота", "lot id", "id_lot"))
    art_ser = t_bd[art].astype(str) if art and art in t_bd.columns else pd.Series("", index=t_bd.index)
    is_lot_art = art_ser.map(_forecast_is_lot_value)
    _mps_lotid_col = "ЛОТ_ID" if "ЛОТ_ID" in out.columns else None
    _per_lot_done = False
    if lotid_col is not None and _mps_lotid_col is not None:
        lotid_ser = t_bd[lotid_col].astype(str).str.strip()
        _plan_sel = plan_mask & is_lot_art
        _fact_sel = fact_mask & is_lot_art
        plan_map = (
            amt_num.loc[_plan_sel].groupby(lotid_ser.loc[_plan_sel]).sum().to_dict()
            if bool(_plan_sel.any()) else {}
        )
        fact_map = (
            amt_num.loc[_fact_sel].groupby(lotid_ser.loc[_fact_sel]).sum().to_dict()
            if bool(_fact_sel.any()) else {}
        )
        for _bad in ("", "nan", "none", "None"):
            plan_map.pop(_bad, None)
            fact_map.pop(_bad, None)
        if plan_map or fact_map:
            ids = out[_mps_lotid_col].astype(str).str.strip()
            counts = ids.value_counts()

            def _per_lot(idv, m):
                v = m.get(idv)
                if v is None or idv in ("", "nan", "none", "None"):
                    return 0.0
                c = int(counts.get(idv, 1)) or 1
                return float(v) / c

            out["budget plan"] = [float(_per_lot(i, plan_map)) for i in ids]
            out["budget fact"] = [float(_per_lot(i, fact_map)) for i in ids]
            try:
                out.attrs["forecast_bddcs_injected_from_1c"] = True
                out.attrs["forecast_bddcs_per_lot"] = True
            except Exception:
                pass
            _per_lot_done = True
    if _per_lot_done:
        return out

    if "budget plan" in out.columns:
        w = pd.to_numeric(out["budget plan"], errors="coerce").fillna(0.0)
    else:
        w = pd.Series(0.0, index=out.index)
    wsum = float(w.sum())
    _fc_uniform_lot_weights = False
    if wsum <= 0 and (plan_sum > 0 or fact_sum > 0):
        _fc_uniform_lot_weights = True
        w = pd.Series(1.0, index=out.index)
        wsum = float(len(out))
    if wsum > 0 and (plan_sum > 0 or fact_sum > 0):
        out["budget plan"] = w / wsum * float(plan_sum)
        out["budget fact"] = w / wsum * float(fact_sum)
        try:
            out.attrs["forecast_bddcs_injected_from_1c"] = True
            if _fc_uniform_lot_weights:
                out.attrs["forecast_bddcs_uniform_lot_weights"] = True
        except Exception:
            pass
    return out


def _forecast_filter_rows_by_plan_end_range(
    work: pd.DataFrame, *, date_from, date_to
) -> pd.DataFrame:
    """Как фильтры БДДС: ограничение строк по календарю по полю plan end."""
    if work is None or getattr(work, "empty", True) or date_from is None or date_to is None:
        return work
    if "plan end" not in work.columns:
        return work
    pe = pd.to_datetime(work["plan end"], errors="coerce")
    if not pe.notna().any():
        return work
    d0 = pd.Timestamp(date_from)
    d1 = pd.Timestamp(date_to)
    if d0 > d1:
        d0, d1 = d1, d0
    return work[
        (pe >= d0)
        & (pe <= (d1 + pd.Timedelta(days=1) - pd.Timedelta(seconds=1)))
    ].copy()


def _forecast_month_calendar_intersects(
    m_per: pd.Period, *, date_from, date_to
) -> bool:
    """Период (месяц/квартал/год) пересекает календарь «С»–«По»."""
    if date_from is None or date_to is None:
        return True
    try:
        p = m_per if isinstance(m_per, pd.Period) else pd.Period(str(m_per), freq="M")
        d0 = pd.Timestamp(date_from)
        d1 = pd.Timestamp(date_to)
        if d0 > d1:
            d0, d1 = d1, d0
        ms = pd.Timestamp(p.start_time)
        me = pd.Timestamp(p.end_time)
        return not (me < d0 or ms > d1)
    except Exception:
        return True


def _forecast_resample_monthly_dataframe(mf: pd.DataFrame, period_type_en: str) -> pd.DataFrame:
    """Месячный mf → месяц / квартал / год (суммы в рублях)."""
    if mf is None or getattr(mf, "empty", True):
        return mf
    if period_type_en == "Month":
        return mf.copy()
    work = mf.copy().reset_index(drop=True)

    def _m_to_ts(x):
        try:
            if isinstance(x, pd.Period):
                return x.to_timestamp(how="start")
            ts = pd.to_datetime(x, errors="coerce", dayfirst=True)
            return pd.NaT if pd.isna(ts) else ts
        except Exception:
            return pd.NaT

    ts = work["month"].map(_m_to_ts)
    try:
        if period_type_en == "Quarter":
            work["_grp"] = ts.dt.to_period("Q")
        else:
            work["_grp"] = ts.dt.to_period("Y")
    except Exception:
        work["_grp"] = ts.apply(
            lambda t: pd.NaT if pd.isna(t) else pd.Period(t, freq=("Q-DEC" if period_type_en == "Quarter" else "Y-DEC"))
        )

    grp = (
        work.dropna(subset=["_grp"])
        .groupby("_grp", sort=True)
        .agg({"bdds_plan_msp": "sum", "bdds_forecast": "sum", "bdds_fact": "sum"})
        .reset_index()
        .rename(columns={"_grp": "month"})
    )
    grp["_dev"] = grp["bdds_plan_msp"] - grp["bdds_forecast"]
    return grp


def _forecast_apply_view_cumulative(mf: pd.DataFrame) -> pd.DataFrame:
    if mf is None or getattr(mf, "empty", True):
        return mf
    out = mf.sort_values("month").copy()
    for c in ("bdds_plan_msp", "bdds_forecast", "bdds_fact"):
        out[c] = pd.to_numeric(out[c], errors="coerce").fillna(0.0).cumsum()
    out["_dev"] = out["bdds_plan_msp"] - out["bdds_forecast"]
    return out



def _forecast_row_lot_label(r: pd.Series) -> str:
    """Подпись лота в таблице: section → lot → block → название задачи."""
    for col in ("section", "lot"):
        if col in r.index:
            s = _clean_display_str(r.get(col))
            if s:
                return s
    for col in ("BLOCK", "block"):
        if col in r.index:
            s = _clean_display_str(r.get(col))
            if s:
                return s
    if "task name" in r.index:
        s = _clean_display_str(r.get("task name"))
        if s:
            return s
    return "—"


def _forecast_lot_label_series(cur: pd.DataFrame) -> pd.Series:
    if cur is None or getattr(cur, "empty", True):
        return pd.Series(dtype=str)
    return cur.apply(_forecast_row_lot_label, axis=1)



def _forecast_editor_visible_mask(pdf: pd.DataFrame) -> pd.Series:
    """Какие строки показывать в UI редактора (расчёт — по всем строкам project_df)."""
    if pdf is None or getattr(pdf, "empty", True):
        return pd.Series(dtype=bool)
    bp = (
        pd.to_numeric(pdf["budget plan"], errors="coerce").fillna(0.0)
        if "budget plan" in pdf.columns
        else pd.Series(0.0, index=pdf.index)
    )
    bf = (
        pd.to_numeric(pdf["budget fact"], errors="coerce").fillna(0.0)
        if "budget fact" in pdf.columns
        else pd.Series(0.0, index=pdf.index)
    )
    has_sum = (bp > 0.0) | (bf > 0.0)
    ls = None
    if "level structure" in pdf.columns:
        ls = pd.to_numeric(pdf["level structure"], errors="coerce")
    elif "level" in pdf.columns:
        ls = pd.to_numeric(pdf["level"], errors="coerce")
    if ls is not None:
        structural = ls.fillna(99) <= 2
    else:
        structural = pd.Series(False, index=pdf.index)
    return has_sum | (~structural)


def _forecast_deduplicate_msp_rows(pdf: pd.DataFrame) -> pd.DataFrame:
    """Один лот (метка + plan start/end) — одна строка; при дублях оставляем с большей суммой."""
    if pdf is None or getattr(pdf, "empty", True):
        return pdf
    work = pdf.copy().reset_index(drop=True)
    if "plan start" not in work.columns or "plan end" not in work.columns:
        return work
    work["_fc_lot_key"] = _forecast_lot_label_series(work).astype(str).str.strip().str.casefold()
    work["_fc_ps"] = pd.to_datetime(work["plan start"], errors="coerce").dt.normalize()
    work["_fc_pe"] = pd.to_datetime(work["plan end"], errors="coerce").dt.normalize()
    work["_fc_score"] = (
        pd.to_numeric(work.get("budget plan"), errors="coerce").fillna(0.0)
        + pd.to_numeric(work.get("budget fact"), errors="coerce").fillna(0.0)
    )
    work = work.sort_values("_fc_score", ascending=False)
    work = work.drop_duplicates(subset=["_fc_lot_key", "_fc_ps", "_fc_pe"], keep="first")
    return work.drop(columns=["_fc_lot_key", "_fc_ps", "_fc_pe", "_fc_score"], errors="ignore").reset_index(drop=True)


def _forecast_aggregate_by_lot(pdf: pd.DataFrame) -> pd.DataFrame:
    """Один лот = одна строка: группируем по реальному лоту (колонка «ЛОТ»/«lot»),
    суммируем отдельно БДДС план и БДДС факт; даты — мин. «Планируемое начало» и
    макс. «Планируемое окончание» среди строк лота. В редактор попадают только строки-лоты
    (у которых заполнен лот); это убирает дубли строк и БДДС по нелотовым задачам.
    Фолбэк (нет колонки лота / нет лотовых строк) — группировка по прежней метке (section)."""
    if pdf is None or getattr(pdf, "empty", True):
        return pdf
    work = pdf.copy().reset_index(drop=True)
    ensure_budget_columns(work)
    work["plan start"] = pd.to_datetime(work.get("plan start"), errors="coerce", dayfirst=True)
    work["plan end"] = pd.to_datetime(work.get("plan end"), errors="coerce", dayfirst=True)
    work["budget plan"] = pd.to_numeric(work.get("budget plan"), errors="coerce").fillna(0.0)
    work["budget fact"] = pd.to_numeric(work.get("budget fact"), errors="coerce").fillna(0.0)
    _proj = (
        work["project name"].iloc[0]
        if "project name" in work.columns and len(work)
        else ""
    )

    _lot_text_col = "ЛОТ" if "ЛОТ" in work.columns else ("lot" if "lot" in work.columns else None)
    _grouped_by_lot = False
    if _lot_text_col is not None:
        _lot_lbl = work[_lot_text_col].map(_clean_display_str)
        _is_lot = _lot_lbl.map(_forecast_is_lot_value)
        if bool(_is_lot.any()):
            work = work.loc[_is_lot].copy()
            work["_fc_lot"] = _lot_lbl.loc[_is_lot].astype(str).str.strip()
            _grouped_by_lot = True
    if not _grouped_by_lot:
        work["_fc_lot"] = _forecast_lot_label_series(work).astype(str).str.strip()

    rows_out: List[dict] = []
    for _lot, g in work.groupby("_fc_lot", sort=False):
        rows_out.append(
            {
                "project name": (
                    g["project name"].iloc[0] if "project name" in g.columns else _proj
                ),
                "section": _lot,
                "task name": _lot,
                "plan start": g["plan start"].min(),
                "plan end": g["plan end"].max(),
                "budget plan": float(g["budget plan"].sum()),
                "budget fact": float(g["budget fact"].sum()),
            }
        )
    return pd.DataFrame(rows_out)


def _forecast_prepare_msp_slice(pdf_raw: pd.DataFrame, project_display_name: str) -> tuple[Optional[pd.DataFrame], Optional[str]]:
    pdf = pdf_raw.copy()
    ensure_budget_columns(pdf)
    ensure_date_columns(pdf)
    ensure_msp_hierarchy_columns(pdf)
    try:
        from web_loader import _fill_section_from_task_tree

        pdf = _fill_section_from_task_tree(pdf)
    except Exception:
        pass
    if "plan start" not in pdf.columns:
        for _rus in ("Начало", "План начало", "План Начало"):
            if _rus in pdf.columns:
                pdf["plan start"] = pdf[_rus]
                break
    if "plan end" not in pdf.columns:
        for _rus in ("Окончание", "План окончание", "План Окончание"):
            if _rus in pdf.columns:
                pdf["plan end"] = pdf[_rus]
                break
    pdf = _forecast_merge_bddcs_from_1c(pdf, project_display_name)
    if "budget plan" not in pdf.columns:
        pdf["budget plan"] = 0.0
    pdf["budget plan"] = pd.to_numeric(pdf["budget plan"], errors="coerce").fillna(0.0)
    if "budget fact" not in pdf.columns:
        pdf["budget fact"] = 0.0
    pdf["budget fact"] = pd.to_numeric(pdf["budget fact"], errors="coerce").fillna(0.0)

    missing_dates = [c for c in ("plan start", "plan end") if c not in pdf.columns]
    if missing_dates:
        return None, f"Нужны колонки дат: {', '.join(missing_dates)}."

    if "section" not in pdf.columns:
        pdf["section"] = ""
    if "Название" in pdf.columns and "task name" not in pdf.columns:
        pdf["task name"] = pdf["Название"]
    if "lot" in pdf.columns:
        _sec_s = pdf["section"].astype(str).str.strip()
        _lot_s = pdf["lot"].astype(str).str.strip()
        pdf["section"] = _sec_s.mask(_sec_s.eq("") | _sec_s.str.lower().isin(("nan", "none", "")), _lot_s)
    pdf["section"] = pdf["section"].apply(_clean_display_str)
    if "task name" not in pdf.columns:
        pdf["task name"] = ""
    pdf = _forecast_deduplicate_msp_rows(pdf)
    return pdf, None


def _forecast_combine_monthly_all_projects(scope_df: pd.DataFrame, project_col: str) -> tuple[pd.DataFrame, float, Optional[str]]:
    """Сводка по всем проектам: суммирование месячных рядов; approved total в млн."""
    labs = sorted(
        {_clean_display_str(x) for x in scope_df[project_col].dropna().unique() if str(x).strip()},
        key=lambda s: str(s).casefold(),
    )
    pieces: List[pd.DataFrame] = []
    approved_mln = 0.0
    errs: List[str] = []
    for lab in labs:
        sub = scope_df[
            scope_df[project_col].map(_project_filter_norm_key) == _project_filter_norm_key(str(lab))
        ].copy()
        if sub.empty:
            continue
        prep, prep_err = _forecast_prepare_msp_slice(sub, str(lab))
        if prep is None or prep_err:
            if prep_err:
                errs.append(f"{lab}: {prep_err}")
            continue
        approved_mln += float(pd.to_numeric(prep["budget plan"], errors="coerce").fillna(0.0).sum()) / 1e6
        mdf, merr = calculate_forecast_budget(
            sub,
            edited_data=prep,
            distribution_mode="uniform",
            abc_source=None,
            row_modes=None,
        )
        if merr:
            errs.append(f"{lab}: {merr}")
            continue
        if mdf is None or mdf.empty:
            continue
        pieces.append(mdf)

    if not pieces:
        return pd.DataFrame(), float(approved_mln), "; ".join(errs) if errs else "Нет расчётных строк по проектам."

    acc = pd.concat(pieces, ignore_index=True)
    summed = (
        acc.groupby("month", sort=False)
        .agg({"bdds_plan_msp": "sum", "bdds_forecast": "sum", "bdds_fact": "sum"})
        .reset_index()
    )
    summed["_dev"] = summed["bdds_plan_msp"] - summed["bdds_forecast"]
    summed = summed.sort_values("month").reset_index(drop=True)
    note = "; ".join(errs) if errs else None
    return summed, float(approved_mln), note




def _forecast_norm_month_period(m):
    try:
        if isinstance(m, pd.Period):
            return m.asfreq("M")
        if pd.isna(m):
            return pd.NaT
        ts = pd.Timestamp(m)
        if pd.notna(ts):
            return ts.to_period("M")
    except Exception:
        pass
    try:
        return pd.Period(str(m), freq="M")
    except Exception:
        return m


def _forecast_turnover_monthly_plan_fact(
    project_name: str,
    *,
    date_from=None,
    date_to=None,
) -> dict:
    """Помесячные план/факт из оборотов 1С (отчёт БДДС), руб."""
    try:
        from dashboards.finance_from_1c import (
            _bdds_turnover_g_for_project,
            resolve_budget_turnover_dannye,
        )
    except Exception:
        return {}
    try:
        from dashboards.finance_from_1c import resolve_reference_1c_dannye
        ref_boot = resolve_reference_1c_dannye(_forecast_find_turnover_dataframe())
    except Exception:
        ref_boot = _forecast_find_turnover_dataframe()
    ref = resolve_budget_turnover_dannye(ref_boot)
    prep = _bdds_turnover_g_for_project(
        project_name=str(project_name or ""),
        period_start=date_from,
        period_end=date_to,
        reference_1c_dannye=ref,
        prefer_budget_scenario=True,
    )
    if prep is None:
        return {}
    g, _months, _art, _canon = prep
    out: dict = {}
    for m in sorted(g["_m"].dropna().unique(), key=lambda x: str(x)):
        mk = _forecast_norm_month_period(m)
        if mk is pd.NaT or (isinstance(mk, float) and pd.isna(mk)):
            continue
        if date_from is not None and date_to is not None:
            if not _forecast_month_calendar_intersects(mk, date_from=date_from, date_to=date_to):
                continue
        chunk = g.loc[g["_m"] == m]
        if chunk.empty:
            continue
        plan_v = float(chunk["_plan"].sum())
        fact_v = float(chunk["_fact"].sum())
        if plan_v + fact_v <= 50_000.0:
            continue
        out[mk] = (plan_v, fact_v)
    return out


def _forecast_turnover_monthly_plan_fact_scope(
    project_labels: list,
    *,
    date_from=None,
    date_to=None,
) -> dict:
    """Сумма план/факт по месяцам для списка проектов (руб.)."""
    agg: dict = {}
    for lab in project_labels:
        for m, (pl, fc) in _forecast_turnover_monthly_plan_fact(
            str(lab), date_from=date_from, date_to=date_to
        ).items():
            if m not in agg:
                agg[m] = [0.0, 0.0]
            agg[m][0] += float(pl)
            agg[m][1] += float(fc)
    return {m: (v[0], v[1]) for m, v in agg.items()}


def _forecast_overlay_turnover_on_monthly(
    mf: pd.DataFrame,
    turnover: dict,
) -> pd.DataFrame:
    """Подменяет план/факт в помесячном ряду данными оборотов 1С где они есть."""
    if mf is None or getattr(mf, "empty", True):
        return mf
    out = mf.copy()
    if not turnover:
        return out
    fc_by_m = {}
    for _, rr in out.iterrows():
        mk = _forecast_norm_month_period(rr["month"])
        fc_by_m[mk] = float(rr.get("bdds_forecast", 0.0) or 0.0)
    turn_norm = {_forecast_norm_month_period(k): v for k, v in turnover.items()}
    months_all = sorted(set(fc_by_m.keys()) | set(turn_norm.keys()), key=lambda x: str(x))
    rows = []
    for m in months_all:
        plan_rub, fact_rub = turn_norm.get(m, (0.0, 0.0))
        if m not in turn_norm:
            hit = out.loc[out["month"] == m]
            if not hit.empty:
                plan_rub = float(hit.iloc[0].get("bdds_plan_msp", 0.0) or 0.0)
                fact_rub = float(hit.iloc[0].get("bdds_fact", 0.0) or 0.0)
        rows.append(
            {
                "month": m,
                "bdds_plan_msp": plan_rub,
                "bdds_fact": fact_rub,
                "bdds_forecast": float(fc_by_m.get(m, 0.0)),
            }
        )
    return pd.DataFrame(rows).sort_values("month").reset_index(drop=True)






def _forecast_filter_chart_months(
    df: pd.DataFrame,
    *,
    hide_zero_months: bool,
    min_rub: float = None,
) -> pd.DataFrame:
    """Фильтр месяцев для графика: все нули или только краевые пустые месяцы."""
    if df is None or getattr(df, "empty", True):
        return df
    thr = float(_FINANCE_CHART_MIN_MONTH_RUB if min_rub is None else min_rub)
    out = df.sort_values("month").copy()
    pl = pd.to_numeric(out["bdds_plan_msp"], errors="coerce").fillna(0.0)
    fc = pd.to_numeric(out["bdds_fact"], errors="coerce").fillna(0.0)
    fr = pd.to_numeric(out["bdds_forecast"], errors="coerce").fillna(0.0)
    active = (pl.abs() + fc.abs() + fr.abs()) >= thr
    if hide_zero_months:
        return out.loc[active].reset_index(drop=True)
    if not bool(active.any()):
        return out
    idx = np.flatnonzero(active.to_numpy())
    return out.iloc[int(idx[0]) : int(idx[-1]) + 1].reset_index(drop=True)


def _forecast_financier_status_dataset(
    *,
    filtered_scope: pd.DataFrame,
    project_col: str,
    all_projects: bool,
    selected_project_label: Optional[str],
    period_type_en: str,
    date_from,
    date_to,
    single_updated_data: Optional[pd.DataFrame],
    abc_source,
    row_modes,
    monthly_snapshot: Optional[pd.DataFrame] = None,
) -> pd.DataFrame:
    """Строки для таблицы «Статус»: план/факт из оборотов 1С, прогноз после правок лотов."""
    rows: List[dict] = []

    def _append_from_mf(mf: pd.DataFrame, lab: str, turnover: dict) -> None:
        fc_by_m: dict = {}
        if mf is not None and not getattr(mf, "empty", True):
            for _, rr in mf.iterrows():
                mk = _forecast_norm_month_period(rr["month"])
                fc_by_m[mk] = float(rr.get("bdds_forecast", 0.0) or 0.0)
        turn_norm = {_forecast_norm_month_period(k): v for k, v in turnover.items()}
        months_all = sorted(set(fc_by_m.keys()) | set(turn_norm.keys()), key=lambda x: str(x))
        if not months_all and mf is not None and not getattr(mf, "empty", True):
            months_all = list(mf["month"])
        for m in months_all:
            plan_rub = 0.0
            fact_rub = 0.0
            if m in turn_norm:
                plan_rub, fact_rub = turn_norm[m]
            elif mf is not None and not getattr(mf, "empty", True):
                hit = mf.loc[mf["month"].map(_forecast_norm_month_period) == m]
                if not hit.empty:
                    plan_rub = float(hit.iloc[0].get("bdds_plan_msp", 0.0) or 0.0)
                    fact_rub = float(hit.iloc[0].get("bdds_fact", 0.0) or 0.0)
            rows.append(
                {
                    "_period": m,
                    "Проект": str(lab),
                    "plan_rub": plan_rub,
                    "fact_rub": fact_rub,
                    "forecast_rub": float(fc_by_m.get(m, 0.0)),
                }
            )

    if (
        not all_projects
        and monthly_snapshot is not None
        and not getattr(monthly_snapshot, "empty", True)
    ):
        lab = str(selected_project_label or "").strip()
        if lab:
            turnover = _forecast_turnover_monthly_plan_fact(
                lab, date_from=date_from, date_to=date_to
            )
            mf = monthly_snapshot.sort_values("month").copy()
            if date_from is not None and date_to is not None:
                _keep_m = mf["month"].map(
                    lambda m: _forecast_month_calendar_intersects(
                        m, date_from=date_from, date_to=date_to
                    )
                )
                mf = mf.loc[_keep_m].reset_index(drop=True)
            mf = _forecast_resample_monthly_dataframe(mf, period_type_en)
            _append_from_mf(mf, lab, turnover)
    elif all_projects:
        labs = sorted(
            {_clean_display_str(x) for x in filtered_scope[project_col].dropna().unique() if str(x).strip()},
            key=lambda s: str(s).casefold(),
        )
        for lab in labs:
            sub = filtered_scope[
                filtered_scope[project_col].map(_project_filter_norm_key)
                == _project_filter_norm_key(str(lab))
            ].copy()
            if sub.empty:
                continue
            prep, prep_err = _forecast_prepare_msp_slice(sub, str(lab))
            if prep is None or prep_err:
                continue
            mdf, merr = calculate_forecast_budget(
                sub,
                edited_data=prep,
                distribution_mode="uniform",
                abc_source=None,
                row_modes=None,
            )
            if merr or mdf is None or getattr(mdf, "empty", True):
                continue
            mf = mdf.sort_values("month").copy()
            if date_from is not None and date_to is not None:
                _keep_m = mf["month"].map(
                    lambda m: _forecast_month_calendar_intersects(
                        m, date_from=date_from, date_to=date_to
                    )
                )
                mf = mf.loc[_keep_m].reset_index(drop=True)
            mf = _forecast_resample_monthly_dataframe(mf, period_type_en)
            turnover = _forecast_turnover_monthly_plan_fact(
                str(lab), date_from=date_from, date_to=date_to
            )
            _append_from_mf(mf, str(lab), turnover)
    else:
        lab = str(selected_project_label or "").strip()
        if not lab:
            return pd.DataFrame()
        sub = filtered_scope.copy()
        prep, prep_err = _forecast_prepare_msp_slice(sub, lab)
        if prep is None or prep_err:
            return pd.DataFrame()
        ed = single_updated_data if single_updated_data is not None else prep
        mdf, merr = calculate_forecast_budget(
            sub,
            edited_data=ed,
            distribution_mode="uniform",
            abc_source=abc_source,
            row_modes=row_modes,
        )
        if merr or mdf is None or getattr(mdf, "empty", True):
            return pd.DataFrame()
        mf = mdf.sort_values("month").copy()
        if date_from is not None and date_to is not None:
            _keep_m = mf["month"].map(
                lambda m: _forecast_month_calendar_intersects(
                    m, date_from=date_from, date_to=date_to
                )
            )
            mf = mf.loc[_keep_m].reset_index(drop=True)
        mf = _forecast_resample_monthly_dataframe(mf, period_type_en)
        turnover = _forecast_turnover_monthly_plan_fact(
            lab, date_from=date_from, date_to=date_to
        )
        _append_from_mf(mf, lab, turnover)

    out = pd.DataFrame(rows)
    if out.empty:
        return out

    def _stat_txt(v: float) -> str:
        try:
            x = float(v)
        except (TypeError, ValueError):
            return ""
        if x < 0:
            return "Экономия"
        if x > 0:
            return "Перерасход"
        return "Без отклонения"

    out["Месяц"] = out["_period"].apply(format_period_ru)
    out["БДДС (план), млн"] = out["plan_rub"] / 1e6
    out["БДДС (факт), млн"] = out["fact_rub"] / 1e6
    out["БДДС (прогноз), млн"] = out["forecast_rub"] / 1e6
    out["Отклонение по сумме, млн"] = out["БДДС (прогноз), млн"] - out["БДДС (план), млн"]
    out["Статус для финансиста"] = out["Отклонение по сумме, млн"].map(_stat_txt)
    # Сортировка хронологическая по периоду (а не по строке «Месяц»).
    out["_period_sort"] = out["_period"].map(_forecast_norm_month_period)
    disp = (
        out.sort_values(["Проект", "_period_sort"])[
            [
                "Месяц",
                "Проект",
                "БДДС (план), млн",
                "БДДС (факт), млн",
                "БДДС (прогноз), млн",
                "Отклонение по сумме, млн",
                "Статус для финансиста",
            ]
        ].reset_index(drop=True)
    )
    return disp.round(2)




def _forecast_financier_status_table_html(df: pd.DataFrame) -> str:
    """«Статус»: ● зелёный при экономии (прогноз < план), красный при перерасходе."""
    if df is None or getattr(df, "empty", True):
        return "<p>Нет данных для статуса.</p>"
    _col_dev = "Отклонение по сумме, млн"
    _col_stat = "Статус для финансиста"
    green = "hsl(148,100%,63%)"
    red = "hsl(348,100%,63%)"
    neutral_bullet = "#94a3b8"
    parts = [
        "<style>"
        ".fc-st-cell-red, .fc-st-cell-red * { color: hsl(348,100%,63%) !important; }"
        ".fc-st-cell-green, .fc-st-cell-green * { color: hsl(148,100%,63%) !important; }"
        f".fc-table-scroll-wrap thead th {{ position: sticky; top: 0; z-index: 5; "
        f"background-color: {TABLE_HEADER_BG_COLOR} !important; color: {TABLE_TEXT_COLOR}; "
        f"{TABLE_HEADER_FONT_CSS} }}"
        "</style>",
        f'<div class="fc-table-scroll-wrap bi-styled-table-wrap" data-bi-rows="{len(df)}">',
        f'<table class="rendered-table bi-sortable-table bi-sort-click-only" style="width:100%;border-collapse:collapse;background-color:{TABLE_BG_COLOR};color:{TABLE_TEXT_COLOR};font-size:14px;">',
        "<thead><tr>",
    ]
    for c in df.columns:
        _cn = str(c).strip()
        parts.append(
            f'<th style="border:1px solid rgba(255,255,255,0.25);padding:8px 6px;text-align:center;vertical-align:middle;'
            f'background-color:{TABLE_HEADER_BG_COLOR};color:{TABLE_TEXT_COLOR};{TABLE_HEADER_FONT_CSS};" '
            f'data-sort-label="{html_module.escape(_cn, quote=True)}">{html_module.escape(_cn)}</th>'
        )
    parts.append("</tr></thead><tbody>")
    for _, row in df.iterrows():
        parts.append("<tr>")
        for col in df.columns:
            raw = row[col]
            val_esc = html_module.escape("" if pd.isna(raw) else str(raw))
            if col == _col_dev:
                try:
                    num = float(raw)
                except (TypeError, ValueError):
                    num = None
                if num is None or pd.isna(num):
                    parts.append(
                        f'<td style="border:1px solid rgba(255,255,255,0.15); padding:5px 8px;">{val_esc}</td>'
                    )
                elif abs(float(num)) < 1e-9:
                    parts.append(
                        f'<td style="border:1px solid rgba(255,255,255,0.15); padding:5px 8px;">'
                        f'<span style="font-weight:700">{html_module.escape(f"{float(num):.2f}")}</span></td>'
                    )
                else:
                    txt = f"{float(num):+.2f}"
                    txt_esc = html_module.escape(txt)
                    _cls = "fc-st-cell-green" if float(num) < 0 else "fc-st-cell-red"
                    parts.append(
                        f'<td class="{_cls}" style="border:1px solid rgba(255,255,255,0.15); padding:5px 8px; '
                        f'font-weight:700;"><span>{txt_esc}</span></td>'
                    )
            elif col == _col_stat:
                try:
                    dv = float(row.get(_col_dev, float("nan")))
                except (TypeError, ValueError):
                    dv = float("nan")
                if pd.isna(dv) or abs(float(dv)) < 1e-9:
                    bullet = neutral_bullet
                elif dv < 0:
                    bullet = green
                else:
                    bullet = red
                parts.append(
                    f'<td style="border:1px solid rgba(255,255,255,0.15); padding:5px 8px;">'
                    f'<span style="color:{bullet};font-weight:700;font-size:1.12em;margin-right:6px">●</span>'
                    f'<span style="color:{TABLE_TEXT_COLOR};font-weight:600">{val_esc}</span>'
                    "</td>"
                )
            else:
                parts.append(
                    f'<td style="border:1px solid rgba(255,255,255,0.15); padding:5px 8px;">{val_esc}</td>'
                )
        parts.append("</tr>")
    parts.append("</tbody></table></div>")
    return "".join(parts)




def _forecast_row_modes_use_abc(mode_val) -> bool:
    sl = str(mode_val or "").strip().casefold()
    if not sl:
        return False
    if "равном" in sl:
        return False
    if sl.startswith("%") or "a/b/c" in sl or "распредел" in sl:
        return True
    return False


def _forecast_edit_disabled_mask(edit_df: pd.DataFrame) -> pd.DataFrame:
    dis = pd.DataFrame(False, index=edit_df.index, columns=edit_df.columns)
    if "Условие распределения" not in edit_df.columns:
        return dis
    for i in range(len(edit_df)):
        if not _forecast_row_modes_use_abc(edit_df.iloc[i]["Условие распределения"]):
            for c in ("A, %", "B, %", "C, %"):
                if c in dis.columns:
                    dis.at[edit_df.index[i], c] = True
    if "Лот" in dis.columns:
        dis["Лот"] = True
    return dis




