def dashboard_forecast_budget(df):
    """Панель «БДДС (утверждённый/прогнозный)» (ранее «Прогнозный бюджет»)."""
    from auth import get_current_user, get_user_role_display, user_can_edit_forecast_budget
    from dashboards.finance_from_1c import resolve_reference_1c_dannye

    _fc_user = get_current_user() or st.session_state.get("user") or {}
    _fc_role = str(_fc_user.get("role") or "")

    _fc_ref_boot = resolve_reference_1c_dannye()
    if _fc_ref_boot is not None and not _fc_ref_boot.empty:
        st.session_state["reference_1c_dannye"] = _fc_ref_boot


    # Check English name first (alias created in load_data), then Russian
    project_col = None
    if "project name" in df.columns:
        project_col = "project name"
    elif "Проект" in df.columns:
        project_col = "Проект"

    if not project_col:
        st.warning(
            "Колонка 'project name' не найдена. Необходима для работы с прогнозным БДДС."
        )
        return

    df_work = _project_column_apply_canonical(df, project_col)
    filtered_scope = df_work.copy()
    _cal_from_eff = None
    _cal_to_eff = None
    selected_project_scope = None
    period_type_en = "Month"
    period_label = "Месяц"

    with filters_panel(st):
        with filters_selectors(st):
            c1, c2, c3, c4, c5 = st.columns(5, gap="small")
            with c1:
                period_type_ru = st.selectbox(
                    "Группировать по",
                    ["Месяц", "Квартал", "Год"],
                    key="forecast_bddcs_period_group",
                    help="Способ суммирования прогнозного БДДС по времени.",
                )
                _pmap_fc = {"Месяц": "Month", "Квартал": "Quarter", "Год": "Year"}
                period_type_en = _pmap_fc.get(period_type_ru, "Month")
                period_label = {"Month": "Месяц", "Quarter": "Квартал", "Year": "Год"}.get(period_type_en, "Месяц")

            with c2:
                project_opts_fc = ["Все"] + _unique_project_labels_for_select(filtered_scope[project_col])
                selected_project_scope = st.selectbox(
                    "Проект",
                    project_opts_fc,
                    key="forecast_bddcs_project_filter",
                )

            if selected_project_scope != "Все":
                filtered_scope = filtered_scope[
                    filtered_scope[project_col].map(_project_filter_norm_key)
                    == _project_filter_norm_key(selected_project_scope)
                ].copy()

            with c3:
                st.selectbox(
                    "Представление",
                    ["По месяцам", "Накопительно"],
                    key="forecast_bddcs_period_view",
                    help="По умолчанию — как отчёт «БДДС». Накопительно — сумма с начала интервала.",
                )

            ensure_date_columns(filtered_scope)
            with c4:
                if "plan end" in filtered_scope.columns:
                    _pe_fc = pd.to_datetime(filtered_scope["plan end"], errors="coerce")
                    if _pe_fc.notna().any():
                        _def_sf = _pe_fc.min().date() if pd.notna(_pe_fc.min()) else None
                        _def_st = _pe_fc.max().date() if pd.notna(_pe_fc.max()) else None
                        try:
                            _pe_all_fc = pd.to_datetime(df_work["plan end"], errors="coerce")
                            if _pe_all_fc.notna().any():
                                _mn_all_fc = _pe_all_fc.min().date()
                                _mx_all_fc = _pe_all_fc.max().date()
                            else:
                                _mn_all_fc, _mx_all_fc = _def_sf, _def_st
                        except Exception:
                            _mn_all_fc, _mx_all_fc = _def_sf, _def_st

                        _cf_in, _ct_in = period_date_range_input(
                            st,
                            "forecast_bddcs_cal_range",
                            min_value=_mn_all_fc or _def_sf,
                            max_value=_mx_all_fc or _def_st,
                            default=(_def_sf, _def_st) if _def_sf and _def_st else None,
                            help="Диапазон по датам окончания плана MSP.",
                        )

                        filtered_scope = _forecast_filter_rows_by_plan_end_range(
                            filtered_scope, date_from=_cf_in, date_to=_ct_in
                        )
                        _cal_from_eff, _cal_to_eff = _cf_in, _ct_in

        _npk_fc_filters = (
            "__all__"
            if selected_project_scope == "Все"
            else _project_filter_norm_key(str(selected_project_scope))
        )
        with filters_toggles(st):
            _fc_cb1, _fc_cb2, _fc_cb3 = st.columns(3, gap="small")
            with _fc_cb1:
                st.radio(
                    "Отклонение от БДДС прогноз считать к",
                    ["БДДС план", "БДДС факт"],
                    horizontal=True,
                    key=f"forecast_bddcs_dev_base_{_npk_fc_filters}",
                )
            with _fc_cb2:
                st.checkbox(
                    "Скрыть отклонение",
                    value=False,
                    key=f"forecast_bddcs_hide_dev_{_npk_fc_filters}",
                )
    if getattr(filtered_scope, "empty", True):
        st.info("Нет строк для выбранных фильтров.")
        return

    _many_projects_fc = selected_project_scope == "Все"
    _view_type_fc = str(st.session_state.get("forecast_bddcs_period_view", "По месяцам"))

    edited_df_out: pd.DataFrame = pd.DataFrame()
    forecast_budget_df = pd.DataFrame()
    calc_error: Optional[str] = None
    _npk_fc = (
        "__all__"
        if _many_projects_fc
        else _project_filter_norm_key(str(selected_project_scope))
    )
    _tot_approved_mln = 0.0
    _fc_updated_data = None
    _fc_abc_src = None
    _fc_row_modes = None
    _lot_oldnew_df: Optional[pd.DataFrame] = None

    _dev_base_fc = str(st.session_state.get(f"forecast_bddcs_dev_base_{_npk_fc}", "БДДС план"))
    _hide_dev_fc = bool(st.session_state.get(f"forecast_bddcs_hide_dev_{_npk_fc}", False))

    if _many_projects_fc:
        if user_can_edit_forecast_budget(_fc_role):
            st.info(
                "Редактирование лотов в таблице: в фильтре **Проект** выберите **один** проект (не «Все»)."
            )
        forecast_budget_df, _tot_approved_mln, _combine_note = _forecast_combine_monthly_all_projects(
            filtered_scope, project_col
        )
        calc_error = None if not forecast_budget_df.empty else (_combine_note or "Нет данных для расчёта.")
    else:
        project_df, prep_err = _forecast_prepare_msp_slice(filtered_scope, str(selected_project_scope))
        if project_df is None or prep_err:
            st.warning(prep_err or "Не удалось подготовить данные проекта.")
            return
        try:
            _merged_1c = bool(project_df.attrs.get("forecast_bddcs_injected_from_1c"))
        except Exception:
            _merged_1c = False
        # Один лот = одна строка (суммы план/факт по лоту; даты — мин. начало/макс. окончание):
        # убирает дубли строк с лотами в редакторе.
        _lot_attrs = dict(getattr(project_df, "attrs", {}) or {})
        project_df = _forecast_aggregate_by_lot(project_df)
        try:
            project_df.attrs.update(_lot_attrs)
        except Exception:
            pass
        if float(project_df["budget plan"].sum()) == 0.0 and not _merged_1c:
            st.info(
                "В файле нет сумм «Бюджет план» и не найдены обороты 1С для проекта — укажите **БДДС план (утверждённый)** "
                "в редакторе ниже или загрузите обороты БДДС."
            )

        def _build_forecast_edit_frame(pdf: pd.DataFrame) -> pd.DataFrame:
            cur = pdf.copy().reset_index(drop=True)
            ps = pd.to_datetime(cur["plan start"], errors="coerce", dayfirst=True)
            pe = pd.to_datetime(cur["plan end"], errors="coerce", dayfirst=True)
            bp = pd.to_numeric(cur["budget plan"], errors="coerce").fillna(0.0)
            if "budget fact" in cur.columns:
                bf = pd.to_numeric(cur["budget fact"], errors="coerce").fillna(0.0)
            else:
                bf = pd.Series(0.0, index=cur.index)
            plan_start_str = ps.dt.strftime("%Y-%m-%d").fillna("")
            plan_end_str = pe.dt.strftime("%Y-%m-%d").fillna("")
            n = len(cur)
            _block = cur["section"].astype(str)
            if "BLOCK" in cur.columns:
                _blk = cur["BLOCK"].astype(str).str.strip()
                _block = _block.mask(_block.str.strip().eq(""), _blk)
            _lot_lbl = _forecast_lot_label_series(cur)
            return pd.DataFrame(
                {
                    "Раздел": _block,
                    "Лот": _lot_lbl.astype(str),
                    "Условие распределения": ["Равномерно"] * n,
                    "План. начало": plan_start_str,
                    "План. окончание": plan_end_str,
                    "БДДС план (утверждённый), млн руб.": (bp / 1e6).round(4),
                    "БДДС факт, млн руб.": (bf / 1e6).round(4),
                    "A, %": [34.0] * n,
                    "B, %": [33.0] * n,
                    "C, %": [33.0] * n,
                }
            )

        _role_fc = _fc_role
        if not _role_fc and st.session_state.get("authenticated"):
            _role_fc = str((st.session_state.get("user") or {}).get("role") or "")
        _can_edit_finance = user_can_edit_forecast_budget(_role_fc)

        if _can_edit_finance:
            st.subheader("Редактирование данных задач")
            with st.expander("Как редактировать таблицу лотов", expanded=False):
                st.markdown(_FORECAST_EDITOR_HELP_MD)
            st.caption(
                "Поля ввода ниже → **«Применить правки»** (только текущая страница). "
                "Правки в сессии до перезагрузки вкладки."
            )
        else:
            st.subheader("Данные задач (только просмотр)")
            _role_lbl = get_user_role_display(_role_fc) if _role_fc else "не выполнен вход"
            st.warning(
                f"Редактирование недоступно. Ваша роль: **{_role_lbl}**. "
                "Правки в таблице лотов: **Администратор**, **Суперадминистратор**, **РП** или **Финансист**."
            )

        _data_key = f"forecast_edit_data_v8_{_npk_fc}"
        _req_cols = (
            "Раздел",
            "Лот",
            "Условие распределения",
            "План. начало",
            "План. окончание",
            "БДДС план (утверждённый), млн руб.",
            "БДДС факт, млн руб.",
            "A, %",
            "B, %",
            "C, %",
        )

        def _fc_reset_editor_data() -> None:
            st.session_state[_data_key] = _build_forecast_edit_frame(project_df)

        if _data_key not in st.session_state:
            _fc_reset_editor_data()
        elif len(st.session_state[_data_key]) != len(project_df):
            _fc_reset_editor_data()
        else:
            _ed0 = st.session_state[_data_key]
            if any(c not in _ed0.columns for c in _req_cols):
                _fc_reset_editor_data()

        if _can_edit_finance and st.button(
            "Сбросить таблицу к данным файла", key=f"forecast_reset_v8_{_npk_fc}"
        ):
            _fc_reset_editor_data()
            st.rerun()

        _edit_df_live = st.session_state[_data_key].copy()
        _dist_options = ["Равномерно", "% Распределения"]
        _n_lots_all_fc = len(_edit_df_live)
        _scroll_h = int(min(620, max(220, 72 + _n_lots_all_fc * 46)))
        _show_struct_key = f"forecast_show_struct_{_npk_fc}"
        _vis_mask_fc = pd.Series(True, index=project_df.index)
        if not st.session_state.get(_show_struct_key, False):
            _vis_mask_fc = _forecast_editor_visible_mask(project_df)
        _visible_idx_fc = list(np.flatnonzero(_vis_mask_fc.to_numpy()))
        _n_lots_fc = len(_visible_idx_fc)

        if _can_edit_finance:
            _hidden_struct_fc = _n_lots_all_fc - _n_lots_fc
            if _hidden_struct_fc > 0 and not st.session_state.get(_show_struct_key, False):
                st.caption(
                    f"В редакторе **{_n_lots_fc}** из **{_n_lots_all_fc}** строк "
                    f"(скрыто **{_hidden_struct_fc}** служебных узлов MSP без сумм — на график не влияет)."
                )
            st.checkbox(
                "Показать служебные строки (уровень ≤2, без БДДС план/факт)",
                key=_show_struct_key,
                help="Корень проекта и блоки иерархии. Расчёт всегда по полному набору строк MSP.",
            )
            _page_key = f"forecast_edit_page_{_npk_fc}"
            _n_pages_fc = max(
                1,
                int((_n_lots_fc + _FORECAST_LOT_EDITOR_PAGE_SIZE - 1) // _FORECAST_LOT_EDITOR_PAGE_SIZE),
            )
            if _page_key not in st.session_state:
                st.session_state[_page_key] = 1
            if _n_pages_fc > 1:
                st.caption(
                    f"Лотов **{_n_lots_fc}** — редактирование по **{_FORECAST_LOT_EDITOR_PAGE_SIZE}** строк на страницу "
                    f"(иначе страница долго грузится)."
                )
                _pg_cols = st.columns([1, 2, 1], gap="small")
                with _pg_cols[0]:
                    if st.button("←", key=f"forecast_pg_prev_{_npk_fc}", disabled=int(st.session_state[_page_key]) <= 1):
                        st.session_state[_page_key] = max(1, int(st.session_state[_page_key]) - 1)
                        st.rerun()
                with _pg_cols[1]:
                    _cur_pg = st.selectbox(
                        "Страница",
                        list(range(1, _n_pages_fc + 1)),
                        index=max(0, int(st.session_state[_page_key]) - 1),
                        format_func=lambda p: f"Стр. {p} / {_n_pages_fc}",
                        key=f"forecast_pg_sel_{_npk_fc}",
                        label_visibility="collapsed",
                    )
                    st.session_state[_page_key] = int(_cur_pg)
                with _pg_cols[2]:
                    if st.button(
                        "→",
                        key=f"forecast_pg_next_{_npk_fc}",
                        disabled=int(st.session_state[_page_key]) >= _n_pages_fc,
                    ):
                        st.session_state[_page_key] = min(_n_pages_fc, int(st.session_state[_page_key]) + 1)
                        st.rerun()
            _pg = max(1, min(int(st.session_state.get(_page_key, 1) or 1), _n_pages_fc))
            _i0 = (_pg - 1) * _FORECAST_LOT_EDITOR_PAGE_SIZE
            _i1 = min(_i0 + _FORECAST_LOT_EDITOR_PAGE_SIZE, _n_lots_fc)
            _page_orig_idx = _visible_idx_fc[_i0:_i1]
            _slice_df = _edit_df_live.iloc[_page_orig_idx].copy().reset_index(drop=True)
            st.caption(
                f"Строки **{_i0 + 1}–{_i1}** из {_n_lots_fc} в редакторе "
                f"(всего в проекте {_n_lots_all_fc}). **«Применить правки»** — только эта страница."
            )
            _render_forecast_lot_editor_sticky_header()
            _body_h = int(min(540, max(200, 56 + len(_slice_df) * 44)))
            with st.container(height=_body_h, border=True):
                _form_slice = _render_forecast_lot_editor_widgets(
                    _slice_df,
                    key_prefix=f"fcw_{_npk_fc}_p{_pg}",
                    dist_options=_dist_options,
                )
            _fc_apply = st.button(
                "Применить правки",
                type="primary",
                key=f"forecast_apply_{_npk_fc}_p{_pg}",
            )
            if _fc_apply:
                _full = st.session_state[_data_key].copy()
                for _j, _orig_i in enumerate(_page_orig_idx):
                    _full.iloc[_orig_i] = _form_slice.iloc[_j]
                st.session_state[_data_key] = _full
                st.rerun()
            edited_df_out = st.session_state[_data_key].copy()
        else:
            st.dataframe(_edit_df_live, width="stretch", height=_scroll_h, hide_index=True)
            edited_df_out = _edit_df_live.copy()

        ed_rows = edited_df_out.reset_index(drop=True)
        if len(project_df) != len(ed_rows):
            st.error("Несовпадение числа строк таблицы и данных проекта.")
            return
        updated_data, row_modes, abc_src = _forecast_work_df_from_edit_rows(project_df, ed_rows)
        _abc_bad: list[str] = []
        for _i in range(len(ed_rows)):
            if not _forecast_row_modes_use_abc(row_modes.iloc[_i]):
                continue
            _a = ed_rows.iloc[_i]["A, %"]
            _b = ed_rows.iloc[_i]["B, %"]
            _c = ed_rows.iloc[_i]["C, %"]
            if _bdds_abc_is_valid(_a, _b, _c):
                continue
            _lot_lbl = str(ed_rows.iloc[_i].get("Лот", "") or "").strip()
            _abc_bad.append(
                f"{_lot_lbl or f'строка {_i + 1}'}: A+B+C={_bdds_abc_sum(_a, _b, _c):.2f}%"
            )
        if _abc_bad:
            st.error(
                "Для «% Распределения» сумма **A+B+C** должна быть **ровно 100%** "
                "(без автоматической нормализации): "
                + "; ".join(_abc_bad[:8])
            )
            return

        _baseline_edit_key = f"forecast_file_baseline_edit_v8_{_npk_fc}"
        _baseline_monthly_key = f"forecast_file_baseline_monthly_v8_{_npk_fc}"
        if _baseline_edit_key not in st.session_state or len(
            st.session_state[_baseline_edit_key]
        ) != len(project_df):
            st.session_state[_baseline_edit_key] = _build_forecast_edit_frame(project_df).copy()
        _base_ed = st.session_state[_baseline_edit_key]
        _base_work, _base_modes, _base_abc = _forecast_work_df_from_edit_rows(project_df, _base_ed)
        st.session_state[_baseline_monthly_key] = _forecast_monthly_forecast_mln_map(
            _base_work, abc_source=_base_abc, row_modes=_base_modes
        )

        forecast_budget_df, calc_error = calculate_forecast_budget(
            df,
            edited_data=updated_data,
            distribution_mode="uniform",
            abc_source=abc_src,
            row_modes=row_modes,
        )
        _tot_approved_mln = float(pd.to_numeric(ed_rows["БДДС план (утверждённый), млн руб."], errors="coerce").fillna(0.0).sum())
        _fc_updated_data = updated_data
        _fc_abc_src = abc_src
        _fc_row_modes = row_modes

        # «Было → стало» по лотам (исходные значения из файла vs текущие правки):
        # нередактируемая таблица для динамики пересчёта.
        try:
            _base_tot = _forecast_per_lot_distribution_totals(
                _base_work, abc_source=_base_abc, row_modes=_base_modes
            )
            _cur_tot = _forecast_per_lot_distribution_totals(
                updated_data, abc_source=abc_src, row_modes=row_modes
            )
            if not _cur_tot.empty:
                _pcol = "БДДС план (утверждённый), млн руб."
                _fcol = "БДДС факт, млн руб."
                _gcol = "БДДС прогноз (итого), млн руб."
                _base_by_lot = (
                    _base_tot.set_index("Лот") if not _base_tot.empty else pd.DataFrame()
                )
                _on_rows: List[dict] = []
                for _, _cr in _cur_tot.iterrows():
                    _lot = str(_cr.get("Лот", ""))
                    _bp_new = float(_cr.get(_pcol, 0.0) or 0.0)
                    _bf_new = float(_cr.get(_fcol, 0.0) or 0.0)
                    _fc_new = float(_cr.get(_gcol, 0.0) or 0.0)
                    if not _base_by_lot.empty and _lot in _base_by_lot.index:
                        _br = _base_by_lot.loc[_lot]
                        _bp_old = float(_br.get(_pcol, 0.0) or 0.0)
                        _bf_old = float(_br.get(_fcol, 0.0) or 0.0)
                        _fc_old = float(_br.get(_gcol, 0.0) or 0.0)
                    else:
                        _bp_old = _bp_new
                        _bf_old = _bf_new
                        _fc_old = _fc_new
                    _on_rows.append(
                        {
                            "Лот": _lot,
                            "БДДС план было, млн руб.": round(_bp_old, 1),
                            "БДДС план стало, млн руб.": round(_bp_new, 1),
                            "БДДС факт было, млн руб.": round(_bf_old, 1),
                            "БДДС факт стало, млн руб.": round(_bf_new, 1),
                            "Прогноз было, млн руб.": round(_fc_old, 1),
                            "Прогноз стало, млн руб.": round(_fc_new, 1),
                        }
                    )
                if _on_rows:
                    _lot_oldnew_df = pd.DataFrame(_on_rows)
        except Exception:
            _lot_oldnew_df = None


    if calc_error and forecast_budget_df.empty:
        st.error(calc_error)
        return
    if calc_error:
        st.warning(calc_error)

    if forecast_budget_df.empty:
        st.info("Нет данных для расчёта прогнозного БДДС по выбранным фильтрам.")
        return

    mf_fc = forecast_budget_df.sort_values("month").copy()
    if _cal_from_eff is not None and _cal_to_eff is not None:
        _keep_m = mf_fc["month"].map(
            lambda m: _forecast_month_calendar_intersects(m, date_from=_cal_from_eff, date_to=_cal_to_eff)
        )
        mf_fc = mf_fc.loc[_keep_m].reset_index(drop=True)

    mf_fc = _forecast_resample_monthly_dataframe(mf_fc, period_type_en)
    if mf_fc is None or mf_fc.empty:
        st.info("Нет данных после агрегирования по выбранному периоду.")
        return

    if _many_projects_fc:
        _labs_turn_main = sorted(
            {_clean_display_str(x) for x in filtered_scope[project_col].dropna().unique() if str(x).strip()},
            key=lambda s: str(s).casefold(),
        )
    else:
        _labs_turn_main = [str(selected_project_scope)]
    _turn_main = _forecast_turnover_monthly_plan_fact_scope(
        _labs_turn_main,
        date_from=_cal_from_eff,
        date_to=_cal_to_eff,
    )
    mf_fc = _forecast_overlay_turnover_on_monthly(mf_fc, _turn_main)

    mf_tot_snapshot = mf_fc.copy()
    if _view_type_fc == "Накопительно":
        mf_fc = _forecast_apply_view_cumulative(mf_fc)

    mf_fc["Период"] = mf_fc["month"].apply(format_period_ru)
    if _dev_base_fc == "БДДС факт":
        mf_fc["_dev"] = mf_fc["bdds_fact"] - mf_fc["bdds_forecast"]
    else:
        mf_fc["_dev"] = mf_fc["bdds_plan_msp"] - mf_fc["bdds_forecast"]

    chart_title_fc = (
        "БДДС план / факт / прогноз"
        + (" (накопительно)" if _view_type_fc == "Накопительно" else "")
        + f" — {period_label.lower()}"
    )
    st.subheader(chart_title_fc)
    x_label_fc = period_label
    _chart_df = mf_fc.copy()
    _hide_zero_chk = period_type_en == "Month"
    _fc_hide_zero = False
    if _hide_zero_chk:
        _fc_hide_zero = st.checkbox(
            "Скрывать месяцы, где план, факт и прогноз равны 0",
            value=True,
            key=f"forecast_bddcs_hide_zero_{_npk_fc}_{period_type_en}",
        )
    if not _chart_df.empty:
        _chart_df = _forecast_filter_chart_months(
            _chart_df,
            hide_zero_months=bool(_fc_hide_zero) if _hide_zero_chk else False,
        )
    if _chart_df.empty:
        st.info(
            "Нет периодов для графика. Снимите «Скрывать месяцы, где план, факт и прогноз равны 0» "
            "или измените таблицу лотов."
        )
    else:
        _nfc = len(_chart_df)
        _tfs_fc = 10 if _nfc > 24 else 11 if _nfc > 14 else 12
        _bg_fc, _bgg_fc, _bar_w_fc = _finance_plotly_bar_layout(_nfc)
        _bgg_fc = max(float(_bgg_fc), 0.22)
        _leg_fc_pre = max(300, min(460, 280 + int(_nfc * 3.5))) if _nfc > 24 else 300
        _top_px_fc = 120 if _nfc > 12 else 100
        _ch_fc_base = 920 if _nfc <= 20 else int(min(1600, 800 + int(_nfc * 2.2)))
        _ch_fc = int(min(1500, max(_ch_fc_base, _top_px_fc + _leg_fc_pre + 420)))
        _xa_fc = -35 if _nfc > 14 else 0
        _xs_fc = 14
        _px_fc = 440 if _nfc > 12 else 380 if _nfc > 8 else 340 if _nfc > 5 else 300
        _tfs_out_fc = 9 if _nfc > 20 else 10
        _fmt_hover1 = lambda v: format_million_rub(v, decimals=1)  # noqa: E731
        _plan_txt_fc = _finance_bar_text_mln_rub(_chart_df["bdds_plan_msp"], min_abs_mln=0.0)
        _fact_txt_fc = _finance_bar_text_mln_rub(_chart_df["bdds_fact"], min_abs_mln=0.0)
        _frc_txt_fc = _finance_bar_text_mln_rub(_chart_df["bdds_forecast"], min_abs_mln=0.0)
        fig_fc = go.Figure()
        x_fc = _chart_df["Период"].astype(str)
        fig_fc.add_trace(
            go.Bar(
                x=x_fc,
                y=_chart_df["bdds_plan_msp"].div(1e6),
                name="БДДС план",
                marker_color="#2E86AB",
                text=_plan_txt_fc,
                textposition="outside",
                textangle=0,
                cliponaxis=False,
                textfont=dict(size=_tfs_out_fc, color="#e8eef5"),
                customdata=_chart_df["bdds_plan_msp"].apply(_fmt_hover1),
                hovertemplate="<b>%{x}</b><br>БДДС план: %{customdata}<extra></extra>",
            )
        )
        fig_fc.add_trace(
            go.Bar(
                x=x_fc,
                y=_chart_df["bdds_fact"].div(1e6),
                name="БДДС факт",
                marker_color="#A23B72",
                text=_fact_txt_fc,
                textposition="outside",
                textangle=0,
                cliponaxis=False,
                textfont=dict(size=_tfs_out_fc, color="#e8eef5"),
                customdata=_chart_df["bdds_fact"].apply(_fmt_hover1),
                hovertemplate="<b>%{x}</b><br>БДДС факт: %{customdata}<extra></extra>",
            )
        )
        fig_fc.add_trace(
            go.Bar(
                x=x_fc,
                y=_chart_df["bdds_forecast"].div(1e6),
                name="БДДС прогноз",
                marker_color="#F18F01",
                text=_frc_txt_fc,
                textposition="outside",
                textangle=0,
                cliponaxis=False,
                textfont=dict(size=_tfs_out_fc, color="#e8eef5"),
                customdata=_chart_df["bdds_forecast"].apply(_fmt_hover1),
                hovertemplate="<b>%{x}</b><br>БДДС прогноз: %{customdata}<extra></extra>",
            )
        )
        fig_fc.update_layout(
            title_text="",
            yaxis_title="млн. руб.",
            barmode="group",
            bargap=_bg_fc,
            bargroupgap=_bgg_fc,
            hovermode="x unified",
            xaxis=dict(
                title=dict(text=x_label_fc, standoff=_xs_fc),
                tickangle=_xa_fc,
                tickfont=dict(size=11),
            ),
        )
        fig_fc = _apply_finance_bar_label_layout(fig_fc)
        _dtick_fc, _ymax_axis_fc = (10.0, 100.0)
        if not _chart_df.empty:
            _ymax_fc = float(
                np.nanmax(
                    np.concatenate(
                        [
                            _chart_df["bdds_plan_msp"].div(1e6).to_numpy(),
                            _chart_df["bdds_fact"].div(1e6).to_numpy(),
                            _chart_df["bdds_forecast"].div(1e6).to_numpy(),
                        ]
                    )
                )
            )
            if np.isfinite(_ymax_fc) and _ymax_fc > 0:
                _dtick_fc, _ = _finance_bar_yaxis_tight(_ymax_fc, outside_labels=True, tick_stride=4)
                # Верх оси = высота самого высокого столбца (без запаса сверху).
                _ymax_axis_fc = float(_ymax_fc)
                fig_fc.update_layout(
                    yaxis=dict(range=[0, _ymax_axis_fc], dtick=_dtick_fc, tick0=0)
                )
        try:
            fig_fc.update_layout(
                uniformtext=dict(minsize=7, mode="hide"),
                margin=dict(t=110),
            )
        except Exception:
            pass
        _leg_y_fc = -0.34 if _nfc <= 20 else (-0.38 if _nfc <= 36 else -0.44)
        fig_fc = _plotly_legend_horizontal_below_plot(
            fig_fc, bottom_px=_leg_fc_pre, legend_y=_leg_y_fc, top_px=_top_px_fc
        )
        if not _chart_df.empty and np.isfinite(_ymax_fc) and _ymax_fc > 0:
            fig_fc.update_layout(
                yaxis=dict(range=[0, _ymax_axis_fc], dtick=_dtick_fc, tick0=0)
            )
        try:
            fig_fc.update_xaxes(title=dict(text=x_label_fc, standoff=_xs_fc), automargin=True)
        except Exception:
            pass
        fig_fc = apply_chart_background(fig_fc)
        st.caption(
            "Подписи над столбцами (млн руб). Длинный ряд — **прокрутка вправо** в полосе под графиком. "
            "Полные значения — в подсказке при наведении."
        )
        _render_finance_bar_chart(
            fig_fc,
            n_periods=_nfc,
            categories=x_fc.astype(str).tolist(),
            height=_ch_fc,
            caption_below="БДДС (утверждённый/прогнозный)",
            px_per_month=_px_fc,
            force_hscroll=True,
        )

    render_table_subheader(st, "Таблица")
    _period_hdr = period_label
    _dev_col_fc = "Отклонение (план − прогноз), млн руб."
    try:
        _tot_fact_mln = float(pd.to_numeric(mf_tot_snapshot["bdds_fact"], errors="coerce").fillna(0.0).sum() / 1e6)
    except Exception:
        _tot_fact_mln = float("nan")
    _sum_rows = {
        _period_hdr: mf_fc["Период"].astype(str),
        "БДДС план": (mf_fc["bdds_plan_msp"] / 1e6).astype(float),
        "БДДС факт": (mf_fc["bdds_fact"] / 1e6).astype(float),
        "БДДС прогноз": (mf_fc["bdds_forecast"] / 1e6).astype(float),
    }
    if not _hide_dev_fc:
        _sum_rows[_dev_col_fc] = (mf_fc["_dev"] / 1e6).astype(float)
    summary_numeric = pd.DataFrame(_sum_rows)

    _tot_plan_mln = float(
        pd.to_numeric(mf_tot_snapshot["bdds_plan_msp"], errors="coerce").fillna(0.0).sum() / 1e6
    )
    _tot_fc_mln = float(
        pd.to_numeric(mf_tot_snapshot["bdds_forecast"], errors="coerce").fillna(0.0).sum() / 1e6
    )
    _total_row = {
        _period_hdr: "ИТОГО",
        "БДДС план": _tot_plan_mln,
        "БДДС факт": float(_tot_fact_mln) if pd.notna(_tot_fact_mln) else 0.0,
        "БДДС прогноз": _tot_fc_mln,
    }
    if not _hide_dev_fc:
        if _dev_base_fc == "БДДС факт":
            _total_row[_dev_col_fc] = float(_total_row["БДДС факт"]) - _tot_fc_mln
        else:
            _total_row[_dev_col_fc] = _tot_plan_mln - _tot_fc_mln
    summary_numeric = pd.concat([summary_numeric, pd.DataFrame([_total_row])], ignore_index=True)

    _baseline_monthly_key = f"forecast_file_baseline_monthly_v8_{_npk_fc}"
    _baseline_fc_map = st.session_state.get(_baseline_monthly_key) or {}
    _skip_cols_fc = {_period_hdr}
    if not _hide_dev_fc:
        _skip_cols_fc.add(_dev_col_fc)
    _cell_background_fc = pd.DataFrame("", index=summary_numeric.index, columns=summary_numeric.columns)
    summary_display_fc = summary_numeric.copy()
    # Колонка прогноза получает текстовые маркеры ▲/▼ → переводим в object,
    # иначе запись строки в float64-колонку падает с TypeError.
    summary_display_fc["БДДС прогноз"] = summary_display_fc["БДДС прогноз"].astype(object)
    for _i_fc, _r_fc in summary_numeric.iterrows():
        _pk_fc = str(_r_fc[_period_hdr])
        if _pk_fc == "ИТОГО":
            continue
        if not isinstance(_baseline_fc_map, dict):
            continue
        _base_fc = _baseline_fc_map.get(_pk_fc)
        if _base_fc is None:
            continue
        try:
            _cur_fc = float(_r_fc["БДДС прогноз"])
            _base_fc = float(_base_fc)
        except (TypeError, ValueError):
            continue
        if _cur_fc > _base_fc + 1e-6:
            _cell_background_fc.at[_i_fc, "БДДС прогноз"] = "rgba(248,113,113,0.35)"
            summary_display_fc.at[_i_fc, "БДДС прогноз"] = f"{_cur_fc:.1f} ▲"
        elif _cur_fc < _base_fc - 1e-6:
            _cell_background_fc.at[_i_fc, "БДДС прогноз"] = "rgba(110,231,183,0.35)"
            summary_display_fc.at[_i_fc, "БДДС прогноз"] = f"{_cur_fc:.1f} ▼"

    _cond_fc = None
    if not _hide_dev_fc:
        _cond_fc = {_dev_col_fc: {"positive_color": "#6ee7b7", "negative_color": "#f87171"}}
    _render_format_dataframe_html(
        summary_display_fc,
        file_stem="forecast_bddcs_summary",
        key_prefix=f"fcast_summary_{_npk_fc}_{period_type_en}",
        conditional_cols=_cond_fc,
        cell_background=_cell_background_fc,
        finance_decimal_places=1,
        bold_row_indices={summary_numeric.index[-1]},
        table_scroll_max_height_vh=70.0,
    )
    if not _many_projects_fc and _lot_oldnew_df is not None and not _lot_oldnew_df.empty:
        st.subheader("Пересчёт по лотам: было → стало")
        st.caption(
            "Исходные значения — из файла; «стало» — после ваших правок. "
            "Расчёт прогноза распределяет суммы по лоту, затем агрегирует по месяцу."
        )
        _render_format_dataframe_html(
            _lot_oldnew_df,
            file_stem="forecast_bddcs_lot_oldnew",
            key_prefix=f"fcast_oldnew_{_npk_fc}",
            finance_decimal_places=1,
            table_scroll_max_height_vh=60.0,
        )

    _status_disp = _forecast_financier_status_dataset(
        filtered_scope=filtered_scope,
        project_col=project_col,
        all_projects=_many_projects_fc,
        selected_project_label=None if _many_projects_fc else str(selected_project_scope),
        period_type_en=period_type_en,
        date_from=_cal_from_eff,
        date_to=_cal_to_eff,
        single_updated_data=_fc_updated_data,
        abc_source=_fc_abc_src,
        row_modes=_fc_row_modes,
        monthly_snapshot=mf_tot_snapshot if not _many_projects_fc else None,
    )
    st.subheader("Статус")
    render_report_html_table(
        _forecast_financier_status_table_html(_status_disp),
        export_df=_status_disp,
        file_stem="forecast_bddcs_financier_status",
        key_prefix=f"fcast_status_{_npk_fc}_{period_type_en}",
    )



